import { SubjectLessonMatrix } from './types';

export const PORTUGUES_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Fonemas, Letras e Dígrafos (Consonantais e Vocálicos)', ref: 'Fonologia FGV', t: 'Fonema é a menor unidade sonora distintiva da língua, enquanto letra é a sua representação gráfica; ocorre dígrafo quando duas letras representam um único fonema, seja consonantal (lh, nh, ch, rr, ss, qu/gu sem som de u, sc, sç, xc) ou vocálico/nasal (am, an, em, en, im, in, om, on, um, un em final de sílaba).', f: 'Na palavra "TÁXI", há um dígrafo consonantal porque a letra X representa um único som.', exp: 'Em "táxi" e "fixo", a letra X representa DOIS fonemas (/ks/), configurando um dífono (4 letras e 5 fonemas)! Já em "campo", há 5 letras e 4 fonemas (dígrafo vocálico "am").' },
    { sub: 'Encontros Vocálicos: Ditongo, Tritongo e Hiato', ref: 'Fonologia FGV', t: 'O ditongo é o encontro de uma vogal e uma semivogal (ou vice-versa) na mesma sílaba (ex: "pai", "série", e também "amavam" / "também", que terminam em ditongo nasal fonético); o tritongo reúne semivogal + vogal + semivogal na mesma sílaba (ex: "Uruguai", "saguão"); e o hiato ocorre quando duas vogais contíguas ficam em sílabas separadas (ex: "sa-ú-de", "sa-í-da", "vo-o").', f: 'Na palavra "QUEIJO", ocorre um tritongo oral na primeira sílaba ("quei").', exp: 'Pegadinha clássica FGV: em "quei-jo" (como o "u" de "qu" não é pronunciado, formando dígrafo), há apenas um DITONGO ("ei"), e não tritongo! Já em "a-ve-ri-guou" e "en-xá-guam", há tritongo.' },
    { sub: 'Ortografia Oficial: Emprego de S, Z, X, CH, G e J', ref: 'Ortografia Oficial', t: 'Grafam-se com S os sufixos "-ês/-esa" (indicadores de origem/título: burguês, japonesa), "-ense" e "-oso/-osa", bem como os verbos derivados de palavras com S no radical (pesquisar, analisar) e o sufixo "-isar" quando o radical já tem S (análise -> analisar); e grafam-se com Z os sufixos "-ez/-eza" formadores de substantivos abstratos derivados de adjetivos (rígido -> rigidez, belo -> beleza) e "-izar" quando o radical não possui S (economia -> economizar).', f: 'Os vocábulos "paralisação", "pesquisa" e "catequese" devem ser grafados com a letra Z segundo a norma-padrão.', exp: 'Análise -> analisar / paralisar (com S); Catequese -> catequizar, Batismo -> batizar, Síntese -> sintetizar (com Z, pois o radical não termina em S).' },
    { sub: 'Grafia dos Porquês (Por que, Por quê, Porque e Porquê)', ref: 'Ortografia FGV', t: 'Emprega-se "por que" (separado e sem acento) em perguntas diretas/indiretas ("por qual razão") ou como pronome relativo ("pelo qual / pelos quais"); "por quê" (separado e com acento) antes de pausa/ponto; "porque" (junto e sem acento) como conjunção explicativa ou causal ("pois / já que"); e "porquê" (junto e com acento) quando substantivado (precedido de artigo/pronome, equivalendo a "o motivo").', f: 'Na frase "Não sei o porque de tanta demora", o termo destacado está corretamente grafado junto e sem acento.', exp: 'Quando precedido de artigo ("o porquê", "um porquê"), funciona como substantivo e exige escrita junta e com acento circunflexo!' },
    { sub: 'Emprego de Onde / Aonde e Mau / Mal', ref: 'Ortografia e Gramática', t: 'O advérbio/pronome relativo "onde" indica permanência em lugar físico fixo (verbos que regem "em"), enquanto "aonde" indica movimento/destino (verbos que regem a preposição "a", como ir ou chegar a algum lugar); já "mau" é adjetivo (oposto de "bom") e "mal" é advérbio, substantivo ou conjunção temporal (oposto de "bem" ou equivalente a "assim que").', f: 'Na norma culta, é correto usar "onde" para retomar qualquer substantivo abstrato sem ideia de lugar, como em "a inflação onde vivemos".', exp: 'A FGV cobra muito: "onde" só pode retomar LUGAR (físico ou noção espacial clara); para tempo usa-se "quando / em que", e para noções não espaciais usa-se "em que / no qual"!' }
  ],
  1: [
    { sub: 'Compreensão (Intratextual) vs. Interpretação (Extratextual / Inferência)', ref: 'Leitura e Interpretação FGV', t: 'Nos comandos da banca FGV, questões de compreensão ("segundo o texto", "o autor afirma explicitamente") exigem a identificação ou paráfrase fiel de informações literalmente presentes na superfície textual; já questões de interpretação ("infere-se", "deduz-se", "subentende-se") exigem a extração de uma conclusão lógica implícita autorizada pelas pistas do texto, sem extrapolação.', f: 'Inferir uma informação de um texto consiste em copiar literalmente um período do primeiro parágrafo ou inventar uma opinião contrária ao autor.', exp: 'Pressuposto = marcado por uma palavra gatilho no texto (ex: "Pedro parou de fumar" -> pressupõe que fumava antes); Subentendido = dedução contextual pragmática.' },
    { sub: 'Coesão Referencial: Anáfora, Catáfora e Elipse', ref: 'Mecanismos de Coesão FGV', t: 'Na coesão referencial endofórica (dentro do texto), ocorre ANÁFORA quando o termo coesivo retoma um referente já expresso anteriormente, e ocorre CATÁFORA quando o termo coesivo antecipa um referente que será enunciado logo adiante (como nos pronomes demonstrativos "isto / este" ao introduzirem uma explicação seguinte).', f: 'Ocorre catáfora sempre que o pronome pessoal "ele" retoma o sujeito da oração imediatamente anterior.', exp: 'Retoma o que veio ANTES = Anáfora (nesse caso, usa-se "esse / isso"); Antecipa o que vem DEPOIS = Catáfora (usa-se "este / isto").' },
    { sub: 'Emprego Coesivo dos Demonstrativos (Este, Esse, Aquele)', ref: 'Coesão Referencial', t: 'Na referência a dois termos já citados anteriormente no período (ex: "O auditor e o contador reuniram-se"), o demonstrativo "este" (ou "esta/isto") retoma o termo mais próximo (o último citado: "o contador"), enquanto "aquele" (ou "aquela/aquilo") retoma o termo mais distante (o primeiro citado: "o auditor").', f: 'Quando dois elementos são mencionados em sequência, o pronome "este" refere-se sempre ao primeiro elemento mencionado na frase.', exp: 'Regra distributiva FGV: "Aquele" = o 1º mencionado (mais distante); "Este" = o último mencionado (mais próximo).' },
    { sub: 'Coerência Textual: Princípios da Não Contradição, Não Tautologia e Relevância', ref: 'Coerência Textual (Charolles)', t: 'A coerência textual é a harmonia lógica e semântica das ideias do texto, sustentada pelas metarregras de Charolles: repetição (retomada de elementos para manter o fio condutor), progressão (acréscimo de informações novas, evitando a tautologia/circularidade viciosa), não contradição (ausência de incompatibilidade lógica interna) e relação (articulação pertinente entre os fatos).', f: 'Um texto perfeitamente coeso no uso de conectivos gramaticais é sempre, obrigatoriamente, um texto coerente no plano lógico.', exp: 'Pode haver frases gramaticalmente conectadas mas logicamente absurdas ou contraditórias; logo, coesão (costura formal) e coerência (sentido lógico) são distintas e complementares.' },
    { sub: 'Intertextualidade (Citação, Alusão, Paródia e Paráfrase) e Ambiguidade', ref: 'Semântica Textual FGV', t: 'A paráfrase reafirma a ideia de um texto-base com outras palavras mantendo seu sentido original, enquanto a paródia subverte ou ironiza o texto-base com intenção crítica ou humorística; já a ambiguidade (anfibologia) é a duplicidade de sentidos decorrente de má construção sintática (ex: uso impreciso do possessivo "seu/sua" ou má posição de adjuntos).', f: 'A paráfrase tem por objetivo inverter e ridicularizar a tese central do texto original.', exp: 'Paráfrase = mantém o sentido com novas palavras; Paródia = altera/subverte o sentido (frequentemente com humor/ironia).' }
  ],
  2: [
    { sub: 'Tipologia Textual vs. Gêneros Textuais', ref: 'Tipologia e Gêneros (FGV)', t: 'Os tipos textuais (modos de organização do discurso) formam um conjunto fechado e limitado de naturezas linguísticas (Narração, Descrição, Dissertação Expositiva, Dissertação Argumentativa e Injunção), enquanto os gêneros textuais são as infinitas realizações concretas sociocomunicativas do cotidiano (editorial, notícia, receita, bula, crônica, edital).', f: 'Os gêneros textuais resumem-se a apenas três estruturas fixas: narração, descrição e dissertação.', exp: 'Tipos textuais = estrutura interna (narrativo, descritivo, dissertativo, injuntivo - cerca de 5); Gêneros textuais = textos concretos sociais (incontáveis: carta, e-mail, lei, fábula, notícia).' },
    { sub: 'Texto Narrativo: Enredo, Sucessão Temporal e Mudança de Estado', ref: 'Tipologia Narrativa', t: 'O texto narrativo caracteriza-se pela evolução cronológica de ações (relação de anterioridade e posterioridade, predomínio de verbos de ação no pretérito perfeito) envolvendo personagens em determinado tempo e espaço, com uma transformação de situação (situação inicial, conflito, clímax e desfecho).', f: 'A simples listagem estática de características físicas de uma paisagem sem qualquer passagem de tempo constitui um texto essencialmente narrativo.', exp: 'A marca definidora da Narração na prova da FGV é a SUCESSÃO TEMPORAL de acontecimentos (dinamismo / "filme"), enquanto a Descrição é um "retrato estático" (simultaneidade).' },
    { sub: 'Texto Descritivo: Simultaneidade, Adjetivação e Ponto de Vista do Observador', ref: 'Tipologia Descritiva', t: 'O texto descritivo apresenta um retrato verbal simultâneo (estático no tempo) de seres, objetos, cenas ou ambientes, com predomínio de substantivos, adjetivos, locuções adjetivas e verbos de ligação ou no pretérito imperfeito / presente, podendo ser uma descrição objetiva (denotativa, técnica) ou subjetiva (impressões pessoais do observador).', f: 'O texto descritivo tem como objetivo principal defender uma tese política por meio de argumentos de autoridade e silogismos.', exp: 'Na FGV, a descrição é frequentemente comparada a uma fotografia (capta propriedades coexistentes de um objeto ou cena sob a perspectiva de um observador).' },
    { sub: 'Texto Dissertativo-Expositivo (Informativo/Didático) vs. Dissertativo-Argumentativo', ref: 'Tipologia Dissertativa', t: 'Tanto o texto expositivo quanto o argumentativo tratam de conceitos e ideias: o dissertativo-expositivo apresenta saberes, dados e explicações consensuais com impessoalidade, sem buscar persuadir o leitor sobre uma tese polêmica; já o dissertativo-argumentativo defende explicitamente um ponto de vista (tese) por meio de argumentos e estratégias de persuasão.', f: 'Um verbete de enciclopédia ou manual didático de anatomia classifica-se como texto predominantemente injuntivo.', exp: 'Expositivo = informar/esclarecer um tema de modo neutro; Argumentativo = defender uma tese e convencer o leitor (comum em artigos de opinião e editoriais).' },
    { sub: 'Texto Injuntivo (Instrucional vs. Prescritivo / Normativo)', ref: 'Tipologia Injuntiva', t: 'O texto injuntivo orienta ou determina o comportamento do interlocutor, caracterizando-se pelo emprego de verbos no modo imperativo (ou infinitivo/futuro com valor imperativo): divide-se em injuntivo instrucional (orientação não coercitiva, como receitas culinárias e manuais de instruções) e injuntivo prescritivo (imposição coercitiva, como leis, editais de concurso e regulamentos).', f: 'Um edital de concurso público da SEFAZ-BA e uma receita de bolo são exemplos de textos puramente lírico-narrativos.', exp: 'Comandos, instruções de uso, receitas, bulas e normas jurídicas pertencem à tipologia INJUNTIVA.' }
  ],
  3: [
    { sub: 'Denotação (Sentido Próprio/Literal) vs. Conotação (Sentido Figurado/Metafórico)', ref: 'Semântica FGV', t: 'A denotação é o emprego da palavra em seu sentido literal, objetivo e dicionarizado (referencial), ao passo que a conotação é o emprego subjetivo, figurado e simbólico da palavra, dependente do contexto expressivo.', f: 'Na frase "Aquele auditor é uma fera em Direito Tributário", o vocábulo "fera" foi empregado em sentido estritamente denotativo.', exp: '"Fera" no sentido de animal selvagem = denotativo; "fera" no sentido de grande especialista = conotativo (metafórico).' },
    { sub: 'Polissemia vs. Homonímia (Homógrafos, Homófonos e Homônimos Perfeitos)', ref: 'Semântica Lexical', t: 'A polissemia ocorre quando uma MESMA palavra (mesma origem etimológica) desenvolve múltiplos sentidos relacionados entre si (ex: "cabeça" do corpo, "cabeça" do prego, "cabeça" da rebelião); já a homonímia ocorre quando palavras de origens/classes diferentes possuem a mesma grafia (homógrafos: "colher" verbo e "colher" substantivo), o mesmo som (homófonos: "sessão", "seção" e "cessão") ou ambos (homônimos perfeitos: "caminho" substantivo e "caminho" verbo).', f: 'Os vocábulos "acender" (atear fogo) e "ascender" (subir) são exemplos de palavras parônimas com pronúncia diferente.', exp: 'Cuidado na FGV! "Acender" e "ascender", assim como "concertar" e "consertar" ou "censo" e "senso", têm exatamente o MESMO SOM, logo são HOMÔNIMOS HOMÓFONOS (e não parônimos)!' },
    { sub: 'Parônimos Clássicos Cobrados pela FGV', ref: 'Paronímia', t: 'Parônimos são vocábulos com grafia e pronúncia parecidas, mas significados distintos: ratificar (confirmar) vs. retificar (corrigir); infligir (aplicar pena) vs. infringir (violar lei); flagrante (evidente, no ato) vs. fragrante (perfumado); mandado (ordem judicial) vs. mandato (procuração/período político); discriminar (diferenciar) vs. descriminar (absolver/tirar a culpa); iminente (prestes a ocorrer) vs. eminente (ilustre/elevado).', f: 'O verbo "ratificar" significa corrigir um erro de cálculo, enquanto "retificar" significa validar e confirmar um tratado.', exp: 'RAtificar = confirmAr; REtificar = corrigir (deixar REto). Infringir = violar; Infligir = aplicar castigo/multa. Deferir = conceder; Diferir = adiar ou divergir.' },
    { sub: 'Hiperonímia (Termo Mais Geral) e Hiponímia (Termo Mais Específico)', ref: 'Relações Hierárquicas de Sentido', t: 'Na hierarquia semântica de inclusão, o HIPERÔNIMO designa o gênero mais amplo (ex: "tributo", "felino", "veículo") e o HIPÔNIMO designa a espécie mais restrita (ex: "ICMS", "leão", "caminhão"); na coesão textual, um hiperônimo pode sempre retomar anaforicamente seu hipônimo sem perda de verdade referencial.', f: 'O vocábulo "imposto" é hiperônimo de "tributo", pois todo tributo é uma espécie de imposto.', exp: 'Em Direito Tributário e Semântica: "Tributo" é o gênero (HIPERÔNIMO), enquanto "Imposto", "Taxa" e "Contribuição de Melhoria" são as espécies (HIPÔNIMOS)!' },
    { sub: 'Valor Semântico de Adjetivos AntePostos vs. Pospostos ao Substantivo', ref: 'Semântica e Morfossintaxe FGV', t: 'Na língua portuguesa, a mudança de posição de certos adjetivos em relação ao substantivo altera não apenas a classe gramatical em alguns casos, mas também o sentido: "um grande homem" (notável, ilustre - valor subjetivo/conotativo na anteposição) difere de "um homem grande" (de elevada estatura - valor objetivo/descritivo na posposição); analogamente, "certos documentos" (alguns - pronome indefinido) difere de "documentos certos" (corretos - adjetivo).', f: 'As expressões "funcionário simples", "simples funcionário", "pobre homem" e "homem pobre" possuem exatamente o mesmo sentido denotativo.', exp: 'Assunto favorito da FGV! Anteposto ao substantivo = geralmente sentido subjetivo/figurado ("pobre homem" = digno de pena; "novo carro" = outro carro); Posposto ao substantivo = geralmente sentido objetivo/literal ("homem pobre" = sem recursos; "carro novo" = recém-fabricado).' }
  ],
  4: [
    { sub: 'Regras Gerais de Acentuação: Oxítonas, Paroxítonas e Proparoxítonas', ref: 'Acentuação Gráfica', t: 'Todas as proparoxítonas são acentuadas; acentuam-se as oxítonas terminadas em A(s), E(s), O(s), EM, ENS (e nos ditongos abertos éi, éu, ói); e acentuam-se as paroxítonas que NÃO terminam em A(s), E(s), O(s), EM, ENS (isto é, acentuam-se as terminadas em r, x, n, l, i, is, u, us, um, uns, ã, ão, ps e ditongo oral crescente ou decrescente).', f: 'Os vocábulos "rubrica", "recorde", "pudico", "avaro", "ibero" e "filantropo" são proparoxítonos e devem receber acento gráfico.', exp: 'Cuidado: rubrica (ru-BRI-ca), recorde (re-COR-de), pudico, avaro, ibero, nobel e cateter são PAROXÍTONAS terminadas em A/E/O/L/R que NÃO levam acento!' },
    { sub: 'Acentuação dos Ditongos Abertos ÉI, ÉU, ÓI (Novo Acordo Ortográfico)', ref: 'Novo Acordo Ortográfico', t: 'Pelo Novo Acordo Ortográfico, os ditongos abertos "éi", "éu" e "ói" perderam o acento agudo nas palavras PAROXÍTONAS (ex: "ideia", "assembleia", "heroico", "jiboia", "paranoico", "colmeia"), mas MANTIVERAM o acento nas palavras OXÍTONAS e nos MONOSSÍLABOS TÔNICOS (ex: "herói", "anéis", "papéis", "céu", "chapéu", "dói").', f: 'Com o Novo Acordo Ortográfico, as palavras "herói", "chapéu" e "papéis" perderam o acento agudo.', exp: 'Ditongos abertos éi/éu/ói: nas Paroxítonas = SEM acento (ideia, heroico); nas Oxítonas e Monossílabos = COM acento (herói, céu, anéis). E cuidado: "destróier" e "méier" mantêm o acento pela regra das paroxítonas terminadas em R!' },
    { sub: 'Regra do Hiato (I e U Tônicos) e Exceções', ref: 'Regra dos Hiatos', t: 'Acentuam-se o "I" e o "U" tônicos quando formam hiato com a vogal anterior, estando sozinhos na sílaba ou seguidos de S (ex: "sa-ú-de", "pa-ís", "ba-ú", "ego-ís-ta"), EXCETO se forem seguidos de "NH" na sílaba seguinte (ex: "rainha", "moinho") ou se, nas paroxítonas, vierem precedidos de ditongo decrescente (ex: "feiura", "baiuca", "bocaiuva").', f: 'As palavras "saúde", "baú" e "história" são acentuadas pela mesma regra gramatical.', exp: 'Distinção clássica de prova: "sa-ú-de" e "ba-ú" = regra do HIATO; "his-tó-ria", "sé-rie" e "á-gua" = paroxítonas terminadas em DITONGO crescente (ou proparoxítonas eventuais/aparentes)!' },
    { sub: 'Hiatos OO e EE e Acentos Diferenciais (Ter/Vir, Pôr/Por, Pôde/Pode)', ref: 'Acentos Diferenciais', t: 'Foram abolidos os acentos circunflexos dos hiatos "oo" ("voo", "enjoo", "abençoo") e das formas verbais em "eem" ("creem", "leem", "veem", "deem") e os diferenciais de paroxítonas homógrafas ("para" verbo, "pelo" substantivo, "pera", "polo"); porém, PERMANECERAM obrigatórios os acentos diferenciais em "pôr" (verbo) vs. "por" (preposição), "pôde" (pretérito) vs. "pode" (presente), e no plural de "ter/vir" e derivados ("ele tem / eles têm", "ele mantém / eles mantêm", "ele intervém / eles intervêm").', f: 'Pelo Novo Acordo Ortográfico, as formas plurais "eles têm" e "eles mantêm" deixaram de receber acento circunflexo.', exp: 'Monossílabos: ele tem / ele vem (sem acento) vs. eles têm / eles vêm (com circunflexo). Oxítonas derivadas: ele mantém / ele provém (agudo no singular) vs. eles mantêm / eles provêm (circunflexo no plural)!' },
    { sub: 'Abito do Trema e Paroxítonas com Ditongo Nasal ou Oral', ref: 'Novo Acordo Ortográfico', t: 'O trema foi integralmente abolido nas palavras da língua portuguesa ("linguiça", "frequente", "sequência", "tranquilo", "aguentar", "quinquênio"), subsistindo apenas em nomes próprios estrangeiros e seus derivados diretos (ex: "Müller", "mülleriano").', f: 'O trema continua obrigatório nas palavras "cinqüenta" e "conseqüência" nos documentos oficiais.', exp: 'O trema só existe hoje em antropônimos/topônimos estrangeiros (Müller, Bündchen).' }
  ],
  5: [
    { sub: 'Regra Geral do Hífen com Prefixos: Letras Iguais vs. Letras Diferentes', ref: 'Emprego do Hífen', t: 'Na regra geral dos prefixos (auto, contra, extra, infra, intra, neo, proto, pseudo, semi, supra, ultra, anti, arqui, hiper, inter, super): USA-SE hífen quando o segundo elemento começa por "H" ou pela MESMA letra que encerra o prefixo (ex: "anti-inflamatório", "micro-ondas", "inter-regional", "sub-bibliotecário", "contra-ataque"); e JUNTA-SE sem hífen quando o segundo elemento começa por letra DIFERENTE (ex: "autoescola", "infraestrutura", "antissocial", "autorretrato", "intermunicipal", "superinteressante").', f: 'Pelo Novo Acordo Ortográfico, escrevem-se com hífen os vocábulos "auto-escola", "anti-social" e "extra-oficial".', exp: 'Letras iguais = SEPARA com hífen (micro-ondas, anti-inflamatório). Letras diferentes = JUNTA (autoescola, extraoficial), dobrando o R ou S quando o prefixo termina em vogal e a palavra seguinte começa por R ou S (antissocial, contrarreforma, ultrassom)!' },
    { sub: 'Prefixos que SEMPRE Exigem Hífen (Além, Aquém, Recém, Sem, Ex, Vice, Pós, Pré, Pró)', ref: 'Hífen Obrigatório', t: 'Exigem SEMPRE o emprego do hífen os prefixos "além-", "aquém-", "recém-", "sem-", "ex-" (no sentido de estado anterior), "vice-", "soto-", "grão-", "grã-" e as formas tônicas acentuadas "pós-", "pré-" e "pró-" (ex: "recém-nascido", "além-mar", "sem-terra", "ex-diretor", "vice-governador", "pós-graduação", "pré-escolar").', f: 'Os vocábulos "recémnascido", "exmarido" e "pósgraduação" devem ser grafados juntos e sem hífen.', exp: 'Prefixos tônicos acentuados (pré-, pós-, pró-) e ex-, vice-, recém-, além-, aquém-, sem- têm hífen SEMPRE!' },
    { sub: 'Prefixos SUB, SOB, CIRCUM, PAN e CO', ref: 'Casos Especiais de Hífen', t: 'Os prefixos "sub-" e "sob-" usam hífen diante de B, R e H ("sub-base", "sub-região", "sub-humano" ou "subumano", mas junta em "suboficial"); "circum-" e "pan-" usam hífen diante de Vogal, M, N e H ("pan-americano", "circum-navegação"); já o prefixo "co-" aglutina-se em regra com o segundo elemento, MESMO quando este começa pela letra O ("coobrigação", "coordenar", "cooperar", "coautor", "corréu", tirando o H em "coerdeiro" e "coabitar").', f: 'O prefixo "co-" exige hífen obrigatório diante de palavras iniciadas pela vogal O, como em "co-obrigação" e "co-ordenar".', exp: 'Pegadinha clássica FGV: o prefixo "co-" é exceção à regra das vogais iguais e JUNTA quase sempre: coobrigado, coordenar, cooperar, coocupante!' },
    { sub: 'Hífen com MAL e BEM', ref: 'Mal e Bem com Hífen', t: 'O elemento "mal-" exige hífen quando o segundo elemento começa por VOGAL, H ou L ("mal-estar", "mal-humorado", "mal-limpo"), juntando-se diante das demais consoantes ("malcriado", "malmequer", "malvisto"); já o elemento "bem-" exige hífen em regra ("bem-estar", "bem-vindo", "bem-humorado", "bem-aventurado", embora se aglutine em derivados históricos como "benfeito", "benfeitor" e "bendizer").', f: 'Escreve-se "mal-criado" com hífen e "malestar" junto sem hífen.', exp: 'Compare: "bem-estar" e "mal-estar" (ambos com hífen diante de vogal/H); mas diante de consoante (exceto L), mal junta ("malcriado", "malditoso") e bem mantém o hífen ("bem-criado", "bem-vindo").' },
    { sub: 'Compostos sem Elemento de Ligação vs. Locuções com Preposição (Queda do Hífen)', ref: 'Hífen em Palavras Compostas', t: 'Mantêm o hífen os substantivos compostos sem elemento de ligação que constituem unidade semântica ("decreto-lei", "guarda-chuva", "segunda-feira", "arco-íris") e as espécies botânicas/zoológicas ("bem-te-vi", "couve-flor", "pimenta-do-reino"); porém, CAÍRAM os hifens das locuções com preposição/elemento de ligação no meio ("fim de semana", "sala de jantar", "dia a dia", "ponto e vírgula", "mão de obra", "pé de moleque", "cara de pau").', f: 'Pelo Novo Acordo Ortográfico, as expressões "fim-de-semana", "dia-a-dia" e "mão-de-obra" conservam obrigatoriamente o hífen.', exp: 'As únicas exceções de compostos com elemento de ligação que mantiveram o hífen são: "água-de-colônia", "arco-da-velha", "cor-de-rosa", "mais-que-perfeito", "pé-de-meia", "ao deus-dará", "à queima-roupa" e nomes de plantas/animais!' }
  ],
  6: [
    { sub: 'Substantivo: Concreto vs. Abstrato e Derivação Imprópria (Substantivação)', ref: 'Classes de Palavras - Substantivo', t: 'Substantivos concretos designam seres de existência própria/autônoma (reais ou imaginários: "pedra", "vento", "fada", "Deus"), enquanto substantivos abstratos designam ações, estados, qualidades ou sentimentos dependentes de um ser para se manifestarem ("corrida", "beleza", "auditoria", "crescimento"); além disso, qualquer palavra precedida de artigo/determinante sofre derivação imprópria e passa a funcionar como substantivo ("um não", "o viver").', f: 'Os vocábulos "fada", "saci" e "alma" são substantivos abstratos por não poderem ser fotografados.', exp: 'Concreto vs. Abstrato na gramática não depende de ser "físico ou espiritual", mas de ter existência conceitual independente (concreto) ou designar ação/qualidade/estado de outro ser (abstrato)!' },
    { sub: 'Distinção entre Locução Adjetiva (Adjunto Adnominal) e Complemento Nominal (Preposição "DE")', ref: 'Substantivo e Adjetivo (FGV)', t: 'Quando um termo preposicionado ("de + substantivo") liga-se a um substantivo CONCRETO, é sempre Adjunto Adnominal (locução adjetiva); quando se liga a um substantivo ABSTRATO derivado de verbo transitivo: se o termo pratica a ação (valor ativo/subjetivo, ex: "a resposta do aluno"), é Adjunto Adnominal; se o termo sofre/recebe a ação (valor passivo/objetivo, ex: "a cobrança do imposto", "a leitura do livro"), é Complemento Nominal!', f: 'Na expressão "a invenção da imprensa por Gutenberg", o termo "da imprensa" pratica a ação de inventar e classifica-se como adjunto adnominal.', exp: 'Questão presente em quase toda prova da FGV! "A invenção da imprensa" (a imprensa foi inventada = alvo/paciente) = Complemento Nominal; "a invenção de Gutenberg" (Gutenberg inventou = agente) = Adjunto Adnominal!' },
    { sub: 'Flexão de Plural dos Substantivos Compostos', ref: 'Plural dos Compostos', t: 'Nos substantivos compostos unidos por hífen: variam AMBOS os elementos quando formados por substantivo + substantivo ou substantivo + adjetivo/numeral ("couves-flores", "cartas-bilhetes", "obras-primas", "segundas-feiras"); varia APENAS O PRIMEIRO quando unidos por preposição ("pés-de-moleque" antes, hoje "pés de moleque", "pôr do sol -> pores do sol") ou quando o segundo limita o primeiro ("navios-escola", "salários-família"); e varia APENAS O SEGUNDO quando o primeiro é verbo ou palavra invariável ("guarda-chuvas", "abaixo-assinados", "alto-falantes", "vice-diretores").', f: 'O plural correto de "guarda-civil" (policial) e de "guarda-noturno" é "guardas-civil" e "guarda-noturnos".', exp: 'Atenção a "GUARDA": em "guarda-roupa" e "guarda-chuva", "guarda" é verbo (= guardar) -> "guarda-roupas", "guarda-chuvas". Já em "guarda-civil", "guarda-noturno" e "guarda-marinha", "guarda" é substantivo (= o policial/sentinela) e o 2º é adjetivo -> variam AMBOS: "guardas-civis", "guardas-noturnos"!' },
    { sub: 'Grau do Adjetivo (Comparativo e Superlativo) e Adjetivos de Relação vs. Qualificativos', ref: 'Adjetivos (FGV)', t: 'Os adjetivos qualificativos atribuem uma qualidade graduável e aceitam anteposição e variação de grau ("relatório muito claro / claríssimo"); já os adjetivos de RELAÇÃO (derivados de substantivos com valor classificatório objetivo, ex: "auditoria fiscal", "crédito tributário", "energia solar", "produção industrial") vêm sempre POSPOSTOS ao substantivo e NÃO admitem variação de grau ("muito fiscal").', f: 'Na expressão "repartição estadual", o adjetivo "estadual" é qualificativo subjetivo e pode ser flexionado no superlativo "estadualíssimo".', exp: 'A FGV cobra em quase todas as provas a diferença entre Adjetivo Qualificativo (opinião/qualidade graduável) e Adjetivo de Relação (classificação objetiva derivada de substantivo, invariável em grau e sempre posposto)!' },
    { sub: 'Valor Semântico do Artigo Definido vs. Artigo Indefinido', ref: 'Emprego do Artigo', t: 'O artigo definido ("o, a, os, as") individualiza e determina um ser já conhecido no contexto ou tomado em sua totalidade genérica; já o artigo indefinido ("um, uma, uns, umas") introduz no texto um ser novo (mencionado pela 1ª vez), indeterminado, ou assume valor aproximativo diante de numerais ("tinha uns trinta anos") ou enfático.', f: 'Quando um personagem é mencionado pela primeira vez em uma narrativa e depois retomado no parágrafo seguinte, usa-se artigo definido na primeira menção e indefinido na retomada.', exp: 'Na progressão textual: 1ª menção no texto = Artigo Indefinido ("Um contribuinte entrou na repartição..."); retomada anafórica = Artigo Definido ("O contribuinte solicitou certidão...").' }
  ],
  7: [
    { sub: 'Pronomes Pessoais Oblíquos Átonos como Complementos Verbais (O, A, OS, AS vs. LHE, LHES)', ref: 'Emprego dos Pronomes Pessoais', t: 'Os pronomes oblíquos átonos "o, a, os, as" (e suas variantes "lo, la, no, na") exercem sintaticamente a função de OBJETO DIRETO (complementam verbos transitivos diretos), enquanto os pronomes "lhe, lhes" exercem a função de OBJETO INDIRETO (complementam verbos transitivos indiretos regidos de "a/para") ou de adjunto adnominal de posse ("roubaram-lhe a carteira" = a carteira dele).', f: 'De acordo com a norma culta, o verbo "assistir" no sentido de ver/presenciar admite o pronome "lhe" como complemento ("assisti-lhe ontem").', exp: 'Exceções clássicas de VTI que NÃO aceitam "lhe" e exigem "a ele / a ela": assistir (ver), aspirar (desejar), visar (almejar) e proceder!' },
    { sub: 'Adaptação Fonética dos Pronomes O, A, OS, AS (LO, LA e NO, NA)', ref: 'Enclise com Adaptação', t: 'Quando os pronomes "o, a, os, as" vêm pospostos (em ênclise ou mesóclise) a formas verbais terminadas em R, S ou Z, caem essas consoantes e o pronome assume a forma "lo, la, los, las" ("auditar + o = auditá-lo", "fiz + o = fi-lo"); quando a forma verbal termina em som nasal (M, ÃO, ÕE), o pronome assume a forma "no, na, nos, nas" ("entregaram + os = entregaram-nos", "põe + a = põe-na").', f: 'Ao substituir o objeto na frase "Os fiscais analisaram os documentos", obtém-se "Os fiscais analisaram-los".', exp: 'Terminou em R, S, Z -> cai a consoante e vira -lo/-la (analisar + os = analisá-los). Terminou em M, ÃO, ÕE -> mantém tudo e vira -no/-na (analisaram + os = analisaram-nos).' },
    { sub: 'Pronomes Relativos (Que, Quem, O Qual, Cujo, Onde) e Função Sintática', ref: 'Pronomes Relativos', t: 'O pronome relativo "CUJO" (e flexões) indica sempre posse entre um antecedente (possuidor) e um consequente (coisa possuída), concorda em gênero e número com a coisa possuída, NUNCA admite artigo depois de si ("cujo o" é erro grave) e exige preposição antes de si se o verbo/nome da oração adjetiva a pedir ("a lei a cujos artigos obedecemos").', f: 'Na norma-padrão, é correto inserir o artigo definido logo após o pronome relativo "cujo", como em "a empresa cujo o balanço foi auditado".', exp: 'Nunca existe artigo depois de CUJO ("cujo balanço", jamais "cujo o balanço")! E "cujo" exerce sempre a função sintática de Adjunto Adnominal.' },
    { sub: 'Colocação Pronominal: Casos Obrigatórios de Próclise (Fatores Atrativos)', ref: 'Colocação Pronominal', t: 'A próclise (pronome antes do verbo) é obrigatória quando há palavra atrativa antes do verbo (sem pausa/vírgula entre eles): (1) palavras negativas ("não, nunca, jamais, ninguém"); (2) advérbios ("já, sempre, aqui, talvez"); (3) pronomes relativos ("que, quem, onde"), indefinidos ("tudo, alguém, todos") e interrogativos; (4) conjunções subordinativas ("embora, quando, se, porque, que"); e (5) frases optativas ou em "em + gerúndio" ("Em se tratando de...").', f: 'Na norma culta escrita, é correto iniciar um período com pronome oblíquo átono, como em "Me entregaram o relatório hoje".', exp: 'Duas proibições absolutas da norma culta: (1) NUNCA se inicia frase/período com pronome oblíquo átono (nem após ponto e vírgula); (2) NUNCA se usa pronome oblíquo átono após particípio!' },
    { sub: 'Mesóclise e Colocação nas Locuções Verbais', ref: 'Mesóclise e Locuções Verbais', t: 'Com verbos no Futuro do Presente ("entregarei") ou no Futuro do Pretérito ("entregaria"), é PROIBIDA a ênclise: se houver fator atrativo antes do verbo, usa-se a próclise ("Não me entregariam"); se não houver fator atrativo, usa-se obrigatoriamente a MESÓCLISE ("Entregar-me-iam o laudo", "Realizar-se-á a prova").', f: 'É gramaticalmente correto segundo a norma-padrão escrever "Realizará-se amanhã a sessão de julgamento".', exp: 'Futuro do Presente e Futuro do Pretérito NUNCA admitem ênclise! Ou têm fator atrativo (próclise) ou vão para a mesóclise ("Realizar-se-á", "Dar-lhe-ei").' }
  ],
  8: [
    { sub: 'Modos Verbais (Indicativo, Subjuntivo e Imperativo) e Tempos do Indicativo', ref: 'Morfologia e Semântica Verbal', t: 'O modo Indicativo expressa certeza/fato real; o Subjuntivo expressa hipótese, dúvida, desejo ou possibilidade; e o Imperativo expressa ordem, pedido ou conselho. No Indicativo, o Pretérito Perfeito indica ação pontual concluída no passado ("estudou"), o Pretérito Imperfeito indica ação habitual, contínua ou durativa no passado ("estudava"), e o Pretérito Mais-que-perfeito indica uma ação passada ocorrida ANTES de outra também passada ("quando o fiscal chegou, o contribuinte já saíra / tinha saído").', f: 'O pretérito mais-que-perfeito simples (como em "ele fizera" ou "nós cantáramos") indica um fato futuro incerto.', exp: 'A FGV cobra muito o valor semântico do Pretérito Imperfeito (ação contínua/habitual no passado ou cortesia: "Eu queria pedir...") e do Pretérito Mais-que-perfeito (-ra: "fizera", passado do passado).' },
    { sub: 'Correlação de Tempos e Modos Verbais', ref: 'Correlação Verbal FGV', t: 'Na correlação verbal clássica das orações condicionais/temporais: o Futuro do Subjuntivo ("Se você FIZER / Quando ele VIER") correlaciona-se com o Futuro do Presente do Indicativo ("aprenderá / veremos"); já o Pretérito Imperfeito do Subjuntivo ("Se você FIZESSE / Caso ele VIESSE") correlaciona-se com o Futuro do Pretérito do Indicativo ("aprenderia / veríamos").', f: 'Há perfeita correlação verbal padrão na frase "Se o governo mantivesse a alíquota, a arrecadação aumentará no próximo mês".', exp: 'Pares inseparáveis da correlação verbal: (1) Se FIZER (Fut. Subj.) -> FARÁ (Fut. Pres.); (2) Se FIZESSE (Imperf. Subj.) -> FARIA (Fut. Pret.); (3) Se TIVESSE FEITO -> TERIA FEITO.' },
    { sub: 'Conjugação de Verbos Irregulares Críticos (Ver, Vir, Pôr, Ter e Derivados)', ref: 'Verbos Irregulares (MARIO / Ver-Vir)', t: 'Nos verbos derivados de TER, VIR, PÔR e VER (manter, intervir, propor, prever, reaver, requerer): no Futuro do Subjuntivo, "ver/prever" fazem "quando eu VIR / PREVIR", enquanto "vir/intervir" fazem "quando eu VIER / INTERVIER"; no Pretérito Perfeito do Indicativo, "intervir" conjuga-se igual a "vir" ("ele interveio", "nós interviemos"), e "reaver" só se conjuga nas formas em que "haver" possui a letra V ("eu reouve", "eles reouveram").', f: 'A forma correta do verbo "intervir" na 3ª pessoa do singular do pretérito perfeito do indicativo é "o juiz interviu no processo".', exp: 'Campeão de provas: Intervir deriva de VIR -> "ele interveio" (jamais "interviu"), "se ele interviesse", "quando ele intervier", "ele tinha intervindo". E "prever" deriva de VER -> "se ele previr"!' },
    { sub: 'Vozes Verbais: Ativa, Passiva (Analítica e Sintética/Pronominal) e Reflexiva', ref: 'Vozes Verbais', t: 'Na transposição da Voz Ativa ("Os auditores analisaram os balanços") para a Voz Passiva Analítica ("Os balanços foram analisados pelos auditores") ou Passiva Sintética ("Analisaram-se os balanços"), o Objeto Direto da ativa transforma-se no SUJEITO PACIENTE da passiva, o sujeito da ativa vira Agente da Passiva, e o verbo auxiliar "ser" mantém exatamente o mesmo tempo e modo do verbo principal da ativa!', f: 'Na frase "Precisa-se de novos auditores", o pronome "se" é apassivador e a oração encontra-se na voz passiva sintética.', exp: 'Só têm Voz Passiva os verbos que possuem Objeto Direto (VTD e VTDI)! Em "Precisa-se de auditores" (VTI), o "se" é Índice de Indeterminação do Sujeito (voz ativa com sujeito indeterminado).' },
    { sub: 'Formas Nominais do Verbo: Infinitivo, Gerúndio e Particípio (Duplos Particípios)', ref: 'Formas Nominais', t: 'Nos verbos abundantes que possuem duplo particípio (como aceitar, entregar, expulsar, acender, prender, extinguir), emprega-se a forma REGULAR terminada em "-ado/-ido" na voz ativa com os auxiliares TER e HAVER ("tinha aceitado", "havia imprimido/elegido"), e emprega-se a forma IRREGULAR curta na voz passiva com os auxiliares SER e ESTAR ("foi aceito", "está impresso", "foi eleito").', f: 'Segundo a norma-padrão, o verbo "chegar" e o verbo "trazer" possuem particípios irregulares na voz ativa: "tinha chego" e "havia trago".', exp: '"Chegar", "abrir", "cobrir", "escrever", "fazer", "ver", "vir", "pôr" e "trazer" têm um ÚNICO particípio: "chegado", "trazido", "aberto", "escrito", "feito", "visto", "posto"!' }
  ],
  9: [
    { sub: 'Classificação do Sujeito e Verbos Impessoais (Oração Sem Sujeito)', ref: 'Sintaxe do Período Simples', t: 'São verbos impessoais (formam Oração Sem Sujeito e permanecem obrigatoriamente na 3ª pessoa do singular, exceto "ser"): (1) o verbo HAVER no sentido de existir, ocorrer ou indicando tempo decorrido ("Havia muitas dúvidas", "Deve haver soluções", "Há dez anos"); (2) o verbo FAZER indicando tempo decorrido ou clima ("Faz dois meses", "Vai fazer três anos"); e (3) verbos de fenômenos da natureza em sentido literal ("Choveu ontem").', f: 'Na frase "Devem haver muitos candidatos inscritos no concurso", o verbo auxiliar está corretamente flexionado no plural.', exp: 'O verbo HAVER (= existir) transmite sua impessoalidade ao verbo auxiliar na locução verbal: "Deve haver muitos candidatos" (singular); porém, o verbo EXISTIR tem sujeito normal e vai ao plural: "Devem existir muitos candidatos"!' },
    { sub: 'Predicado Verbal, Predicado Nominal e Predicado Verbo-Nominal', ref: 'Tipos de Predicado e Predicativo', t: 'O Predicado Verbal tem como núcleo um verbo significativo (transitivo ou intransitivo, sem predicativo); o Predicado Nominal tem como núcleo um nome (Predicativo do Sujeito) ligado por um Verbo de Ligação (ser, estar, permanecer, ficar, continuar, parecer, andar, tornar-se indicando estado); e o Predicado Verbo-Nominal possui DOIS núcleos simultâneos: um verbo significativo e um predicativo (do sujeito ou do objeto, ex: "Os auditores saíram cansados da reunião" ou "O júri julgou o réu culpado").', f: 'Na frase "O auditor continua na repartição", o verbo "continuar" é de ligação e o predicado é nominal.', exp: 'Verbo de ligação exige (1) ideia de estado + (2) presença de Predicativo do Sujeito! Em "O auditor continua na repartição", "na repartição" é adjunto adverbial de lugar, logo "continuar" é verbo intransitivo e o predicado é VERBAL!' },
    { sub: 'Transitividade Verbal: VTD, VTI, VTDI, VI e Objeto Direto Preposicionado', ref: 'Complementos Verbais', t: 'O Objeto Direto liga-se em regra sem preposição obrigatória ao VTD, e o Objeto Indireto liga-se com preposição obrigatória ao VTI; excepcionalmente, ocorre Objeto Direto Preposicionado quando um VTD recebe preposição por razões estilísticas, para evitar ambiguidade, com pronomes oblíquos tônicos ("Ajudou a mim") ou com sentido partitivo ("Comeu do pão", "Bebeu do vinho").', f: 'Toda vez que um complemento verbal vier iniciado pela preposição "a" ou "de", ele será classificado obrigatoriamente como objeto indireto.', exp: 'Quem define se o objeto é direto ou indireto é a transitividade do verbo: se o verbo é VTD ("amar", "comer", "cumprir", "sacar"), mesmo que venha com preposição ("amar a Deus", "sacar da arma", "cumprir com o dever"), o termo é Objeto Direto Preposicionado!' },
    { sub: 'Complemento Nominal vs. Objeto Indireto vs. Adjunto Adnominal', ref: 'Termos Integrantes vs. Acessórios', t: 'O Objeto Indireto completa o sentido de um VERBO transitivo indireto ("obedecer à lei"); já o Complemento Nominal é um termo preposicionado que completa o sentido transitivo de um NOME — podendo ligar-se a um ADJETIVO ("favorável ao acordo"), a um ADVÉRBIO ("favoravelmente ao acordo") ou a um SUBSTANTIVO ABSTRATO com valor passivo/alvo ("obediência à lei", "respeito às normas").', f: 'O adjunto adnominal pode modificar tanto um substantivo quanto um adjetivo ou um verbo.', exp: 'Regra infalível: Ligado a Adjetivo ou Advérbio -> é SEMPRE Complemento Nominal! Ligado a Substantivo Concreto -> é SEMPRE Adjunto Adnominal! Ligado a Substantivo Abstrato -> Agente/Posse = Adjunto Adnominal; Paciente/Alvo = Complemento Nominal.' },
    { sub: 'Aposto (Explicativo, Restritivo/Especificativo, Enumerativo, Resumitivo e Oracional)', ref: 'Termos Acessórios da Oração', t: 'O aposto é o termo substantivo que explica, resume, enumera ou especifica outro substantivo: o Aposto Explicativo vem isolado por pontuação ("Salvador, capital da Bahia, sedia a SEFAZ"); o Aposto Especificativo individualiza um substantivo genérico sem vírgula ("O rio São Francisco", "O poeta Castro Alves"); e a oração introduzida por "que" após dois-pontos ou substantivo abstrato é uma Oração Subordinada Substantiva Apositiva ("Só desejo uma coisa: que você seja aprovado").', f: 'Na expressão "A cidade de Salvador", o termo "de Salvador" classifica-se como objeto indireto.', exp: 'Em "a cidade de Salvador", "o mês de outubro", "o estado da Bahia", o nome próprio preposicionado especifica o substantivo genérico e classifica-se como Aposto Especificativo!' }
  ],
  10: [
    { sub: 'Orações Coordenadas Sindéticas: Aditivas, Adversativas, Alternativas, Conclusivas e Explicativas', ref: 'Período Composto por Coordenação', t: 'As conjunções coordenativas classificam-se em: Aditivas (e, nem, não só... mas também); Adversativas (mas, porém, contudo, todavia, entretanto, no entanto); Alternativas (ou... ou, ora... ora, quer... quer); Conclusivas (logo, portanto, por conseguinte, pois posposto ao verbo); e Explicativas (porque, que, porquanto, pois anteposto ao verbo após imperativo).', f: 'A conjunção "porquanto" possui valor semântico de oposição adversativa, equivalendo a "entretanto".', exp: 'Atenção máxima na FGV! "Porquanto" equivale a "porque / visto que" (é causal/explicativa, NUNCA adversativa)! E a conjunção "POIS": antes do verbo = explicativa/causal; depois do verbo (entre vírgulas) = conclusiva (= portanto)!' },
    { sub: 'Orações Subordinadas Substantivas (Subjetiva, Objetiva Direta/Indireta, Completiva Nominal, Predicativa e Apositiva)', ref: 'Subordinação Substantiva', t: 'As orações subordinadas substantivas (introduzidas pelas conjunções integrantes "que" ou "se", ou por pronomes/advérbios interrogativos nas indiretas) equivalem a um substantivo ("ISTO"): em "É necessário que todos estudem" ("Isto é necessário"), a segunda oração funciona como SUJEITO da primeira (Subordinada Substantiva Subjetiva); já em "Tenho certeza de que venceremos", completa o substantivo "certeza" (Completiva Nominal).', f: 'Na frase "Convém que os relatórios sejam entregues hoje", a oração destacada é subordinada substantiva objetiva direta.', exp: 'Com expressões de verbo de ligação + predicativo ("É preciso, É necessário, É bom"), na voz passiva ("Sabe-se que..., Foi anunciado que...") ou verbos unipessoais ("Convém que..., Urge que..., Parece que..."), a oração seguinte é sempre SUBJETIVA!' },
    { sub: 'Orações Subordinadas Adjetivas: Restritivas (Sem Vírgula) vs. Explicativas (Com Vírgula)', ref: 'Subordinação Adjetiva (FGV)', t: 'Introduzidas por pronomes relativos (que, quem, o qual, cujo, onde), as Orações Adjetivas Restritivas (SEM vírgulas) limitam o universo do antecedente a um subconjunto específico ("Os servidores que cometeram falta foram punidos" -> apenas os que cometeram falta), enquanto as Explicativas (COM vírgulas) generalizam a informação para a totalidade do grupo antecedente ("Os servidores, que cometeram falta, foram punidos" -> todos os servidores cometeram falta e foram punidos).', f: 'A inserção ou retirada de vírgulas antes de uma oração subordinada adjetiva preserva integralmente o sentido original da frase.', exp: 'Questão obrigatória em 100% das provas da FGV: trocar Adjetiva Restritiva (sem vírgula, particulariza) por Explicativa (entre vírgulas, generaliza/universaliza) mantiene a correção gramatical, mas ALTERA o sentido!' },
    { sub: 'Orações Subordinadas Adverbiais: Causais, Consecutivas, Condicionais, Concessivas e Conformativas', ref: 'Subordinação Adverbial (9 Tipos)', t: 'Nas 9 orações adverbiais: as Concessivas expressam um obstáculo que não impede a ação principal (embora, conquanto, ainda que, mesmo que, posto que, se bem que, apesar de que); as Consecutivas expressam a consequência/efeito (tão/tanto/tamanho... que, de modo que); as Conformativas expressam acordo/conformidade (conforme, como, segundo, consoante); e as Proporcionais expressam simultaneidade gradual (à medida que, à proporção que, quanto mais... mais).', f: 'As locuções conjuntivas "posto que" e "conquanto" introduzem orações adverbiais explicativas.', exp: 'Cuidado na FGV: "Posto que", "conquanto", "malgrado" e "não obstante" têm valor CONCESSIVO (= embora)! E "na medida em que" = Causal (= porque), enquanto "à medida que" = Proporcional!' },
    { sub: 'Orações Reduzidas de Infinitivo, Gerúndio e Particípio', ref: 'Orações Reduzidas', t: 'As orações subordinadas reduzidas não são iniciadas por conjunção nem pronome relativo e apresentam o verbo em uma das três formas nominais (infinitivo, gerúndio ou particípio), mantendo a mesma classificação sintática da forma desenvolvida correspondente (ex: "Terminada a auditoria, o fiscal lavrou o auto" = Subordinada Adverbial Temporal Reduzida de Particípio).', f: 'Uma oração reduzida de gerúndio nunca pode exercer a função de oração subordinada adverbial condicional ou adjetiva.', exp: 'Para classificar qualquer oração reduzida, basta desenvolvê-la inserindo a conjunção ou pronome relativo adequado ("Quando terminou a auditoria..." = Temporal; "Ao assinar o termo..." = Temporal).' }
  ],
  11: [
    { sub: 'Concordância Verbal com Sujeito Composto (Anteposto vs. Posposto ao Verbo)', ref: 'Concordância Verbal', t: 'Quando o sujeito composto vem ANTES do verbo, o verbo vai obrigatoriamente para o plural (salvo núcleos sinônimos, em gradação ou resumidos por "tudo/nada/ninguém"); porém, quando o sujeito composto vem POSPOSTO (depois do verbo), admite-se a concordância lógica no plural OU a concordância atrativa com o núcleo mais próximo ("Faltaram / Faltou coragem e tempo aos candidatos").', f: 'Quando o sujeito composto vem posposto ao verbo, a concordância com o núcleo mais próximo no singular é considerada erro gramatical.', exp: 'Sujeito composto ANTES do verbo = Plural obrigatório; Sujeito composto DEPOIS do verbo = Plural OU concorda com o núcleo mais próximo!' },
    { sub: 'Concordância com Partículas Apassivadoras vs. Índices de Indeterminação e Expressões Partitivas', ref: 'Concordância com o SE e Partitivos', t: 'Na voz passiva sintética (VTD/VTDI + SE), o verbo concorda obrigatoriamente com o sujeito paciente ("Alugam-se salas", "Devem-se analisar os autos"); já com VTI, VI ou VL + SE (índice de indeterminação do sujeito), o verbo fica obrigatoriamente na 3ª pessoa do singular ("Trata-se de questões complexas", "Necessita-se de técnicos"). Em expressões partitivas ("A maioria dos fiscais...") ou porcentagens ("1,8% dos alunos" / "20% da turma"), o verbo pode concordar com o núcleo partitivo/numeral ou com o especificador.', f: 'Na frase "Tratam-se de medidas urgentes para o Estado", o verbo está corretamente flexionado no plural.', exp: 'Quem trata, trata DE algo (VTI) -> logo, em "Trata-se de...", o verbo fica SEMPRE no singular!' },
    { sub: 'Concordância dos Verbos DAR, BATER, SOAR (Horas) e do Verbo SER', ref: 'Concordância do Verbo SER e Horas', t: 'Na indicação de horas, datas e distâncias, o verbo SER é impessoal e concorda com o numeral do predicativo ("É uma hora", "São duas horas", "Hoje são 28 de outubro" ou "Hoje é dia 28 de outubro"); já os verbos DAR, BATER e SOAR concordam com o sujeito "relógio/sino" se expresso ("O relógio deu cinco horas") ou com o número de horas se "relógio" não for o sujeito ("Deram cinco horas no relógio da matriz").', f: 'Na indicação de horas, é correto dizer "É duas horas da tarde" porque o verbo ser permanece invariável.', exp: 'O verbo SER também concorda obrigatoriamente no plural com o predicativo quando o sujeito é "tudo, isso, isto, aquilo, o que" ("Tudo são flores") e fica no singular nas expressões de quantidade "é muito, é pouco, é suficiente" ("Cem reais é pouco").' },
    { sub: 'Concordância Nominal: Adjetivo Anteposto vs. Posposto a Mais de um Substantivo', ref: 'Concordância Nominal', t: 'Quando um adjetivo na função de adjunto adnominal vem ANTEPOSTO a dois ou mais substantivos, concorda em regra com o substantivo mais próximo ("Escolheu má hora e lugar"); quando vem POSPOSTO aos substantivos, pode concordar com o mais próximo OU ir para o plural (prevalecendo o masculino plural se houver gêneros diferentes: "Comprei livro e revista novos / nova").', f: 'Quando um adjetivo posposto refere-se a um substantivo masculino e a um feminino no plural, a única concordância aceita é o feminino singular.', exp: 'Se o adjetivo anteposto funcionar como Predicativo do Sujeito ou do Objeto ("Estavam desertos a rua e o largo", "Julgo necessários o empenho e a dedicação"), vai ao plural!' },
    { sub: 'Concordância de Palavras Especiais: Anexo, Mesmo, Próprio, Quite vs. Bastante, Meio, Menos, Alerta', ref: 'Casos Especiais de Concordância Nominal', t: 'Variam em gênero e número concordando com o substantivo: "anexo, incluso, obrigado, quite, leso, mesmo/próprio (= em pessoa)" ("Seguem anexas as planilhas", "Estamos quites", "Elas mesmas assinaram"). São INVARIÁVEIS: a palavra "menos", o advérbio "alerta" ("Os vigias ficaram alerta"), a expressão "em anexo", e os termos "meio" (= um pouco) e "bastante" (= muito) quando funcionam como advérbios ("Ela estava meio cansada", "Eles são bastante dedicados", embora variem como adjetivos/pronomes: "meia colher", "bastantes provas").', f: 'Na frase "A candidata ficou meia nervosa porque tinha menas chances", a concordância nominal segue o padrão culto.', exp: 'A palavra "menas" não existe na língua portuguesa! E "meio" modificando adjetivo ("meio nervosa", "meio abertas") é advérbio de intensidade -> INVARIÁVEL!' }
  ],
  12: [
    { sub: 'Regência de Verbos Críticos (Assistir, Aspirar, Visar, Implicar, Preferir, Esquecer/Lembrar, Obedecer)', ref: 'Regência Verbal FGV', t: 'Na norma-padrão: (1) Assistir (ver) e Aspirar (almejar) são VTI (regem "a": "assistiu ao jogo", "aspira ao cargo"); (2) Obedecer e Desobedecer são SEMPRE VTI ("obedeceu ao regulamento"); (3) Implicar no sentido de acarretar/produzir consequência é VTD SEM preposição ("O atraso implicará multa", jamais "implicará em"); (4) Preferir é VTDI com a preposição "A", rejeitando "do que" e intensificadores ("Prefiro estudar A trabalhar"); e (5) Esquecer e Lembrar sem pronome são VTD ("Esqueci o livro"), mas quando pronominais são VTI com "DE" ("Esqueci-me DO livro").', f: 'De acordo com a gramática normativa, o verbo "implicar" no sentido de acarretar exige a preposição "em" ("A reforma implicará em aumento").', exp: 'Três erros de regência mais cobrados na FGV: (1) "implicar em" no sentido de acarretar (o correto é VTD direto: "implicar algo"); (2) "preferir mais X do que Y" (o correto é "preferir X a Y"); (3) "namorar com alguém" (namorar é VTD: "namorar alguém").' },
    { sub: 'Regência com Pronomes Relativos (Anteposição Obrigatória da Preposição)', ref: 'Regência com Pronomes Relativos', t: 'Em orações subordinadas adjetivas, toda preposição exigida pelo verbo (ou pelo nome) da oração adjetiva deve ser obrigatoriamente deslocada para ANTES do pronome relativo ("O cargo a que aspiro", "A lei a que obedecemos", "O livro de que gostei", "A cidade a que chegamos", "A empresa em cujos dados confiamos").', f: 'Na norma culta, a frase "O filme que assistimos ontem foi premiado" apresenta regência verbal correta.', exp: 'Quem assiste (no sentido de ver), assiste A alguma coisa -> logo, o correto é "O filme A QUE assistimos ontem"!' },
    { sub: 'Regra Geral da Crase e Casos de Proibição Absoluta', ref: 'Emprego da Crase', t: 'A crase é a fusão da preposição "a" com o artigo definido feminino "a(s)" (ou com o "a" inicial dos demonstrativos "aquele(s), aquela(s), aquilo" e dos relativos "a qual, as quais"). Por isso, NUNCA ocorre crase antes de: (1) palavras masculinas ("a prazo", "a pé"); (2) verbos ("a partir de", "começou a falar"); (3) pronomes pessoais, de tratamento (exceto senhora/senhorita/dona), indefinidos ("a todas", "a qualquer", "a ninguém") e demonstrativos "esta/essa"; (4) palavras femininas no plural precedidas de "a" no singular ("Refiro-me a situações graves"); e (5) expressões com palavras repetidas ("gota a gota", "cara a cara", "dia a dia").', f: 'Ocorre crase obrigatória antes de verbos no infinitivo e em expressões de palavras repetidas, como em "frente à frente" e "a partir".', exp: '"A" no singular diante de palavra no plural -> CRASE NEM A PAU! ("Falei a pessoas amigas" = sem crase; "Falei às pessoas amigas" = com crase).' },
    { sub: 'Casos de Crase Obrigatória (Locuções Femininas, Horas Exatas e Paralelismo)', ref: 'Crase Obrigatória', t: 'É obrigatório o acento grave indicativo de crase nas locuções adverbiais, prepositivas e conjuntivas de base feminina ("às vezes", "à noite", "à tarde", "às pressas", "à vista", "à direita", "à espera de", "à procura de", "à medida que", "à proporção que"), na indicação de horas determinadas ("Sairemos às 14h", salvo após as preposições para, desde, após, entre) e na locução "à moda de" mesmo subentendida ("bife à milanesa", "gol à Pelé").', f: 'Nas locuções adverbiais femininas de instrumento como "escrever a mão" ou "barco a vela", o Novo Acordo exige crase obrigatória.', exp: 'Em locuções femininas de INSTRUMENTO ("a mão", "a máquina", "a tinta", "a bala", "a vela"), em regra não se usa crase (ou é facultativa apenas para evitar ambiguidade).' },
    { sub: 'Casos de Crase Facultativa e Casos Especiais (Casa, Terra, Distância e Nomes de Lugar)', ref: 'Crase Facultativa e Especiais', t: 'A crase é FACULTATIVA em três casos: (1) antes de pronomes possessivos femininos adjetivos no singular ("Refiro-me a / à minha irmã"); (2) antes de nomes próprios femininos de pessoa ("Entreguei o prêmio a / à Maria"); e (3) depois da preposição "ATÉ" seguida de palavra feminina ("Fui até a / até à praia"). Nas palavras "casa" (lar) e "terra" (chão firme), só há crase se vierem especificadas ("Voltei a casa" vs. "Voltei à casa de meus pais"); em "distância", só há crase se determinada ("Viu a distância" vs. "Viu à distância de cem metros").', f: 'Na frase "Os marinheiros voltaram à terra firme após meses no mar", o emprego da crase em "à terra" é incorreto.', exp: 'Cuidado! "Voltaram a terra" (sem especificador) = sem crase; "Voltaram à terra firme" ou "à terra natal" (COM especificador "firme" / "natal") = COM crase obrigatória! E para topônimos: "Vou a, volto DA -> crase HÁ! Vou a, volto DE -> crase PRA QUÊ?" ("Vou à Bahia, vou a Salvador").' }
  ],
  13: [
    { sub: 'Proibição Absoluta de Vírgula entre Termos Essenciais e Integrantes (SVC)', ref: 'Pontuação - Vírgula (FGV)', t: 'Na ordem direta (Sujeito + Verbo + Complementos Verbais / Nome + Complemento Nominal ou Adjunto Adnominal), é terminantemente PROIBIDO separar por uma única vírgula o sujeito do seu verbo (mesmo que o sujeito seja longo ou oracional), o verbo dos seus objetos (direto ou indireto), ou o nome do seu complemento nominal / adjunto adnominal.', f: 'Quando o sujeito de uma oração é muito extenso, a gramática recomenda colocar uma vírgula logo antes do verbo.', exp: 'Mesmo com 3 linhas de sujeito, NUNCA se põe uma vírgula simples entre o Sujeito e o Verbo ("Quem casa quer casa" -> "Quem estuda para o concurso da SEFAZ-BA conquistará a vaga", sem vírgula antes de "conquistará")!' },
    { sub: 'Emprego da Vírgula para Deslocamento, Isolamento e Enumeração', ref: 'Usos da Vírgula', t: 'Emprega-se a vírgula para: (1) separar termos de mesma função sintática em uma enumeração; (2) isolar o vocativo, o aposto explicativo e expressões explicativas/retificativas ("isto é, ou seja, por exemplo, aliás"); (3) isolar adjuntos adverbiais deslocados (obrigatória se longos; facultativa se curtos); (4) isolar orações subordinadas adverbiais antepostas ou intercaladas (e adjetivas explicativas); e (5) marcar a elipse (zeugma) de um verbo ("O Estado cobra o ICMS; o Município, o ISS").', f: 'Em uma oração subordinada adverbial deslocada para o início do período, o uso da vírgula após ela é proibido.', exp: 'Ordem inversa (Oração Subordinada Adverbial ANTES da Principal) -> Vírgula OBRIGATÓRIA! Ordem direta (Principal antes da Adverbial) -> Vírgula facultativa (exceto nas consecutivas).' },
    { sub: 'Vírgula Antes da Conjunção "E" (Sujeitos Diferentes e Polissíndeto)', ref: 'Vírgula com a Conjunção E', t: 'Como regra geral, não se usa vírgula antes da conjunção aditiva "e"; contudo, a vírgula antes do "e" é permitida (e recomendada) quando as orações coordenadas possuem SUJEITOS DIFERENTES ("O auditor lavrou o auto, e o contribuinte apresentou defesa"), quando o "e" assume valor adversativo (= mas: "Estudou muito, e não passou") ou no polissíndeto enfático ("E trabalha, e estuda, e vence").', f: 'O emprego de vírgula antes da conjunção "e" constitui erro gramatical em absolutamente qualquer contexto da língua portuguesa.', exp: 'Na FGV: orações ligadas por "e" com SUJEITOS DIFERENTES admitem vírgula perfeitamente!' },
    { sub: 'Emprego dos Dois-Pontos (:)', ref: 'Dois-Pontos (FGV)', t: 'Os dois-pontos anunciam uma pausa suspensiva para introduzir: (1) uma citação ou fala em discurso direto; (2) uma enumeração explicativa de termos; (3) um aposto explicativo ou oração subordinada substantiva apositiva; ou (4) um esclarecimento, síntese, causa ou consequência direta da afirmação anterior (podendo nesse caso substituir conectivos explicativos/causais ou conclusivos).', f: 'Os dois-pontos só podem ser utilizados na língua portuguesa antes de listas com marcadores numéricos.', exp: 'Questão clássica FGV: os dois-pontos frequentemente introduzem uma EXPLICAÇÃO/CAUSA ou uma CONCLUSÃO/SÍNTESE do que foi dito antes!' },
    { sub: 'Emprego do Ponto e Vírgula (;), Travessões e Parênteses', ref: 'Ponto e Vírgula e Travessões', t: 'O ponto e vírgula marca uma pausa intermediária entre a vírgula e o ponto: separa itens de enumerações complexas (especialmente incisos de leis ou cláusulas que já contêm vírgulas internas) e separa orações coordenadas extensas ou simétricas (especialmente antes de conjunções adversativas/conclusivas deslocadas ou quando há zeugma verbal); já o par de travessões ou parênteses pode substituir o par de vírgulas em apostos explicativos e intercalações com maior ênfase.', f: 'Um único travessão isolado no meio da frase pode separar o sujeito simples do seu verbo intransitivo.', exp: 'Quando o conectivo adversativo/conclusivo ("porém, contudo, todavia, entretanto, portanto, logo") vem deslocado para depois do verbo da 2ª oração, usa-se ponto e vírgula antes da 2ª oração e o conectivo fica entre vírgulas ("Estudou bastante; o exame, porém, foi difícil").' }
  ],
  14: [
    { sub: 'Nominalização (Transformação de Oração Desenvolvida em Sintagma Nominal)', ref: 'Reescritura de Frases FGV', t: 'A nominalização consiste em substituir um verbo (ou uma oração subordinada) por um substantivo cognato abstrato derivado desse verbo (ex: "Quando os impostos aumentaram, o consumo caiu" $\\to$ "Com o aumento dos impostos, houve queda do consumo"), o que confere maior concisão, impessoalidade e densidade informacional ao texto técnico/argumentativo.', f: 'Na nominalização de uma oração, transforma-se todo substantivo abstrato em um advérbio de modo terminado em "-mente".', exp: 'Tópico favorito da FGV em Reescritura! Verbo $\\to$ Substantivo Abstrato ("desenvolveram a pesquisa" $\\to$ "o desenvolvimento da pesquisa"); Adjetivo $\\to$ Substantivo ("porque era ágil" $\\to$ "pela agilidade").' },
    { sub: 'Equivalência entre Conjunções e Locuções Prepositivas nas Reescrituras', ref: 'Equivalência de Conectivos FGV', t: 'Na reescritura mantendo o sentido original: (1) Concessão ("Embora chovesse, saiu") equivale a "Apesar da chuva / Não obstante a chuva / Conquanto chovesse / A despeito de chover"; (2) Causa ("Como choveu / Já que choveu / Visto que choveu / Porquanto choveu") equivale a "Em virtude da chuva / Graças à chuva / Por ter chovido"; (3) Condição ("Caso chova / Desde que chova / Contanto que chova / A menos que não chova"); e (4) Finalidade ("Para que vença / A fim de vencer").', f: 'A substituição de "Embora houvesse crise" por "Porquanto houvesse crise" mantém o valor concessivo original.', exp: '"Embora / Conquanto / Posto que / Mesmo que" = Concessão. "Porquanto / Já que / Visto que / Uma vez que / Como (no início)" = Causa!' },
    { sub: 'Equivalência por Transposição de Voz Verbal e Mudança de Ordem', ref: 'Paráfrase Estrutural FGV', t: 'Transpor uma oração da voz ativa para a voz passiva (analítica ou sintética) mantém o sentido referencial básico (mudando apenas o foco/tema para o paciente), desde que se preservem o tempo verbal e os agentes; já inverter a ordem de termos pode exigir ajustes ou causar mudança de sentido se envolver advérbios focalizadores como "só, apenas, somente, até, mesmo".', f: 'As frases "Só o auditor assinou o relatório", "O auditor só assinou o relatório" e "O auditor assinou só o relatório" possuem exatamente o mesmo sentido.', exp: 'Cuidado extremo na FGV: mudar a posição de palavras restritivas/inclusivas ("só, apenas, somente, principalmente, até, mesmo") ALTERA completamente o escopo e o sentido da frase!' },
    { sub: 'Eliminação do Gerundismo e Paralelismo Sintático e Semântico', ref: 'Paralelismo e Clareza FGV', t: 'O paralelismo sintático exige que ideias coordenadas de valor similar sejam expressas com a mesma estrutura gramatical (ex: "Gosto de ler e de escrever", "Não só pelos custos, mas também pelos prazos"; é falha de paralelismo misturar um substantivo com uma oração desenvolvida: "Precisamos de transparência e que todos colaborem" $\\to$ o correto é "de transparência e da colaboração de todos").', f: 'Há perfeito paralelismo sintático na frase "O edital exige formação superior, experiência na área e que o candidato tenha disponibilidade para viajar".', exp: 'Para manter o paralelismo na lista de 3 objetos diretos nominais: "exige formação superior, experiência na área e disponibilidade para viajar" (3 substantivos).' },
    { sub: 'Discurso Direto vs. Discurso Indireto vs. Discurso Indireto Livre', ref: 'Transposição de Discursos', t: 'Na transposição do Discurso Direto (fala literal da personagem) para o Discurso Indireto (mediado por verbo dicendi + que/se): a 1ª pessoa passa para a 3ª ("eu" $\\to$ "ele"), os demonstrativos/advérbios de proximidade recuam ("isto, aqui, hoje, ontem, amanhã" $\\to$ "aquilo, lá, naquele dia, na véspera, no dia seguinte"), e os tempos verbais recuam um grau para o passado (Presente $\\to$ Imperfeito; Pretérito Perfeito $\\to$ Mais-que-perfeito; Futuro do Presente $\\to$ Futuro do Pretérito; Imperativo $\\to$ Imperfeito do Subjuntivo).', f: 'Na passagem do discurso direto "Eu farei a auditoria amanhã" para o indireto com verbo no passado ("Ele disse que..."), a forma correta é "Ele disse que eu farei a auditoria amanhã".', exp: 'Tabela de recuo no Discurso Indireto: "Eu farei amanhã" $\\to$ "Ele disse que FARIA (Futuro do Pretérito) no dia seguinte"!' }
  ],
  15: [
    { sub: 'Figuras de Palavras (Tropos): Metáfora, Comparação, Metonímia, Catacrese, Sinestesia e Antonomásia', ref: 'Figuras de Linguagem FGV', t: 'A Comparação (símile) aproxima dois seres usando conectivo explícito ("como, tal qual"), enquanto a Metáfora faz uma comparação implícita sem conectivo; a Metonímia substitui um termo por outro com relação objetiva de contiguidade (autor pela obra: "Li Machado de Assis"; continente pelo conteúdo: "Comeu dois pratos"; parte pelo todo; marca pelo produto); a Catacrese é uma metáfora desgastada por falta de termo próprio ("braço da cadeira", "dente de alho", "embarcar no avião"); e a Sinestesia cruza sensações de órgãos dos sentidos diferentes ("voz doce", "perfume quente", "olhar frio").', f: 'Na frase "O estádio inteiro aplaudiu o jogador", ocorre uma metáfora poética por semelhança subjetiva.', exp: '"O estádio aplaudiu" (o lugar pelas pessoas que estão dentro dele), "Beber um copo d\'água" (continente pelo conteúdo) e "Viver do suor do rosto" (efeito pela causa / meio) são exemplos clássicos de METONÍMIA!' },
    { sub: 'Figuras de Pensamento: Antítese, Paradoxo (Oxímoro), Eufemismo, Hipérbole, Ironia e Prosopopeia', ref: 'Figuras de Pensamento', t: 'A Antítese aproxima palavras de sentidos opostos sem ferir a lógica ("O ódio e o amor caminham juntos"); já o Paradoxo (ou oxímoro) funde ideias opostas em uma mesma afirmação aparentemente absurda/autocontraditória ("É ferida que dói e não se sente", "Estou cego de tanto ver"); o Eufemismo suaviza uma ideia desagradável ("faltou com a verdade", "entregou a alma a Deus"); a Hipérbole é o exagero intencional ("morrer de rir", "chorar rios de lágrimas"); a Ironia diz o contrário do que se pensa com tom crítico; e a Prosopopeia (personificação) atribui ações humanas a seres inanimados.', f: 'Na frase "Depois da luz vem a escuridão", ocorre um paradoxo lógico insolúvel.', exp: 'Luz vs. escuridão sucedendo-se = Antítese (oposição sem contradição lógica); "Luz escura" ou "silêncio ensurdecedor" = Paradoxo / Oxímoro (contradição interna).' },
    { sub: 'Figuras de Sintaxe (Construção): Elipse, Zeugma, Pleonasmo, Hipérbato, Polissíndeto, Assíndeto, Anáfora e Silepse', ref: 'Figuras de Sintaxe', t: 'A Elipse é a omissão de um termo facilmente subentendido, e o Zeugma é o tipo específico de elipse em que se omite um termo JÁ expresso anteriormente no período ("Uns preferem Direito; outros, Contabilidade"); o Hipérbato (ou anástrofe) é a inversão violenta da ordem direta dos termos ("Ouviram do Ipiranga as margens plácidas..."); e a Silepse é a concordância ideológica (com a ideia, e não com a forma gramatical: de número, de gênero como "Vossa Excelência está preocupado", ou de pessoa como "Os brasileiros somos otimistas").', f: 'Em "Os baianos somos muito hospitaleiros", há um erro grave de concordância verbal sem justificativa estilística.', exp: 'Sujeito na 3ª pessoa ("Os baianos") com verbo na 1ª pessoa do plural ("somos", porque quem fala se inclui no grupo) é a clássica Silepse de Pessoa!' },
    { sub: 'Vícios de Linguagem: Barbarismo, Solecismo, Cacofonia,Eco, Pleonasmo Vicioso e Ambiguidade', ref: 'Vícios de Linguagem', t: 'O Barbarismo é o desvio na pronúncia, grafia ou morfologia de uma palavra isolada ("advinhar", "interviu"); o Solecismo é o desvio sintático de concordância, regência ou colocação ("Houveram problemas", "Assisti o filme"); e o Pleonasmo Vicioso (redundância inútil) repete uma ideia já contida no próprio significado da palavra ("elo de ligação", "encarar de frente", "monopólio exclusivo", "há dois anos atrás", "adiar para depois").', f: 'As expressões "criar novos empregos", "elo de ligação" e "consenso geral" são exemplos de figuras estilísticas recomendadas na redação oficial.', exp: 'A FGV cobra muito a identificação de redundâncias (pleonasmos viciosos): "há anos atrás" ("há" e "atrás" repetem passado), "elo de ligação" (todo elo já é de ligação), "acabamento final", "planejar antecipadamente".' },
    { sub: 'Síntese FGV de Língua Portuguesa para a SEFAZ-BA', ref: 'Revisão Geral Português FGV', t: 'Pontos de maior incidência na banca FGV: (1) diferença entre Adjunto Adnominal (agente/posse ou ligado a concreto) e Complemento Nominal (paciente/alvo de substantivo abstrato ou ligado a adjetivo/advérbio); (2) diferença de sentido entre Adjetiva Restritiva (sem vírgula, particulariza) e Explicativa (com vírgula, generaliza); (3) valor e posição do adjetivo (qualificativo vs. de relação); (4) impessoalidade de "haver" (= existir) vs. "existir"; e (5) reescritura por nominalização e conectivos (conquanto/posto que = concessão; porquanto = causa/explicação).', f: 'Para a banca FGV, toda oração introduzida pela palavra "que" é classificada como oração coordenada sindética aditiva.', exp: 'Dominar a distinção entre Pronome Relativo "que" (= o qual -> introduz Oração Adjetiva) e Conjunção Integrante "que" (troca por ISTO -> introduz Oração Substantiva) resolve mais de 30% das questões gramaticais da FGV!' }
  ]
};

export const INFORMATICA_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Arquitetura de Von Neumann: CPU (ULA, UC e Registradores)', ref: 'Hardware Básico', t: 'Na arquitetura de Von Neumann, a Unidade Central de Processamento (CPU) compõe-se da Unidade Lógica e Aritmética (ULA, que executa cálculos e comparações), da Unidade de Controle (UC, que busca, decodifica e coordena a execução das instruções) e dos Registradores (memória interna de altíssima velocidade no topo da hierarquia).', f: 'A Unidade Lógica e Aritmética (ULA) é um dispositivo de armazenamento magnético secundário localizado fora do processador.', exp: 'Dentro da CPU ficam: ULA + UC + Registradores (mais a memória Cache L1/L2/L3).' },
    { sub: 'Hierarquia de Memórias: Voláteis (RAM, Cache, Registradores) vs. Não Voláteis (ROM, Flash, SSD, HD)', ref: 'Memórias de Computador', t: 'As memórias RAM (DRAM) e Cache (SRAM) são memórias voláteis (perdem seu conteúdo na ausência de energia elétrica); já a memória ROM (BIOS/UEFI) e as memórias secundárias de massa (SSD baseado em memória Flash NAND e HD magnético) são não voláteis.', f: 'A memória RAM mantém todos os arquivos abertos salvos permanentemente mesmo quando o computador é desligado da tomada.', exp: 'Voláteis = Registradores, Cache (SRAM) e Principal (RAM/DRAM). Não voláteis = ROM, EEPROM/Flash, SSD, HD, Pen drive.' },
    { sub: 'Memória Cache (SRAM) vs. Memória Principal (DRAM)', ref: 'Memórias Cache e RAM', t: 'A memória Cache é construída com tecnologia SRAM (Static RAM, mais rápida, mais cara, menor capacidade e que não precisa de ciclos constantes de refresh), enquanto a memória principal utiliza tecnologia DRAM (Dynamic RAM, baseada em capacitores que exigem refresh periódico).', f: 'A memória Cache possui capacidade de armazenamento em terabytes superior à do disco rígido (HD).', exp: 'Na pirâmide de memória (do topo para a base): Registradores -> Cache L1/L2/L3 (SRAM) -> RAM (DRAM) -> SSD/HD (aumenta a capacidade e o tempo de acesso; diminui o custo por bit e a velocidade).' },
    { sub: 'Barramentos, Interfaces (USB, HDMI, SATA, NVMe/PCIe) e Periféricos', ref: 'Barramentos e Periféricos', t: 'Os dispositivos de armazenamento SSD no padrão M.2 NVMe comunicam-se através do barramento PCI Express (PCIe), alcançando taxas de leitura e escrita muito superiores aos SSDs e HDs conectados pelo barramento SATA III (limitado a 6 Gbps, cerca de 600 MB/s).', f: 'O monitor de vídeo padrão (sem tela sensível ao toque) e a impressora jato de tinta simples são periféricos exclusivamente de entrada.', exp: 'Periféricos de Entrada = teclado, mouse, scanner, microfone; Saída = monitor comum, impressora simples, caixa de som; Entrada/Saída (mistos) = tela touchscreen, multifuncional, placa de rede, pendrive.' },
    { sub: 'Software Básico (Sistema), Software Aplicativo, Firmware e Licenciamento', ref: 'Classificação de Software', t: 'O Sistema Operacional (Windows, Linux) e os drivers de dispositivos classificam-se como softwares de sistema (básicos); editores de texto, planilhas e navegadores são softwares aplicativos; e o Firmware (BIOS/UEFI) é o conjunto de instruções gravado diretamente em memória não volátil (ROM/Flash) do hardware.', f: 'O software livre (Open Source) proíbe o acesso ao código-fonte e impede a redistribuição de cópias modificadas.', exp: 'As 4 liberdades do Software Livre (FSF): executar para qualquer fim (0), estudar/adaptar com acesso ao código-fonte (1), redistribuir cópias (2) e distribuir versões modificadas (3).' }
  ],
  1: [
    { sub: 'Gerenciamento de Arquivos e Sistemas de Arquivos no Windows (NTFS, FAT32 e exFAT)', ref: 'Windows 10/11', t: 'O sistema de arquivos padrão das versões atuais do Windows (10 e 11) é o NTFS (New Technology File System), que suporta permissões de segurança por usuário (ACL), criptografia (EFS), compactação nativa, registro de transações (journaling) e arquivos maiores que 4 GB (limite do antigo FAT32).', f: 'No Windows 10/11, é permitido nomear um arquivo utilizando os caracteres especiais barra (/), asterisco (*), interrogação (?) e dois-pontos (:).', exp: 'Os 9 caracteres PROIBIDOS em nomes de arquivos/pastas no Windows (mnemônico "BASICO"): \\ / : * ? " < > |.' },
    { sub: 'Comportamento de Arrastar e Soltar (Drag and Drop) e Exclusão (Lixeira vs. Shift+Delete)', ref: 'Explorador de Arquivos', t: 'No Explorador de Arquivos do Windows: ao arrastar um arquivo com o botão esquerdo entre pastas da MESMA unidade/partição (ex: de C:\\Fotos para C:\\Docs), a ação padrão é MOVER (ou se pressionar Ctrl, copiar); ao arrastar entre unidades DIFERENTES (ex: de C: para o pendrive D:), a ação padrão é COPIAR (ou se pressionar Shift, mover).', f: 'Pressionar o atalho Shift + Delete sobre um arquivo no disco rígido envia o arquivo para a Lixeira com prioridade máxima.', exp: 'Delete (ou Ctrl + D) = envia para a Lixeira (exceto arquivos de unidades de rede ou pendrive, que são excluídos direto); Shift + Delete = exclui permanentemente SEM passar pela Lixeira!' },
    { sub: 'Atalhos de Teclado Clássicos do Windows 10/11 (Tecla Windows + Letra)', ref: 'Atalhos do Windows (FGV)', t: 'No Windows 10/11: Win + E abre o Explorador de Arquivos; Win + D exibe/oculta a Área de Trabalho; Win + L bloqueia a sessão do computador; Win + V abre o Histórico da Área de Transferência; Win + I abre as Configurações; Win + Shift + S abre a captura de tela; e Ctrl + Shift + Esc abre diretamente o Gerenciador de Tarefas.', f: 'O atalho de teclado Alt + F4 no Windows serve para atualizar a página ativa, enquanto F5 fecha o programa em execução.', exp: 'F5 = Atualizar; Alt + F4 = Fechar janela ativa; Alt + Tab = Alternar entre janelas abertas; Win + Tab = Visão de Tarefas (Desktops Virtuais).' },
    { sub: 'Área de Transferência Múltipla (Win + V) e Restauração da Lixeira', ref: 'Recursos do Windows 10/11', t: 'Quando um arquivo que está na Lixeira do Windows é restaurado, ele retorna automaticamente para a sua pasta de origem original (e caso a pasta original tenha sido excluída, o Windows a recria); porém, arquivos dentro da Lixeira não podem ser abertos/executados diretamente sem antes serem restaurados.', f: 'É possível editar e salvar normalmente um documento do Word diretamente dentro da Lixeira do Windows sem restaurá-lo.', exp: 'Na Lixeira, ao dar duplo clique sobre um arquivo, abre-se apenas a janela de Propriedades (com o botão Restaurar), não o conteúdo do arquivo.' },
    { sub: 'Pontos de Restauração do Sistema vs. Backup de Arquivos Pessoais', ref: 'Recuperação no Windows', t: 'A ferramenta "Restauração do Sistema" do Windows reverte arquivos de sistema, configurações do Registro e drivers para um Ponto de Restauração anterior, mas NÃO afeta nem recupera documentos pessoais do usuário (como fotos ou planilhas excluídas).', f: 'A Restauração do Sistema apaga todos os documentos pessoais criados pelo usuário após a data do ponto de restauração.', exp: 'Ponto de Restauração = recupera Sistema/Drivers/Registro (não toca em arquivos pessoais); Histórico de Arquivos / Backup = recupera arquivos pessoais.' }
  ],
  2: [
    { sub: 'Classificação das Redes por Abrangência (PAN, LAN, MAN, WAN) e Intranet vs. Extranet', ref: 'Redes de Computadores', t: 'A Intranet é uma rede privada corporativa que utiliza os mesmos protocolos da Internet (pilha TCP/IP, HTTP) com acesso restrito aos colaboradores internos da organização; já a Extranet ocorre quando parte controlada dessa Intranet é estendida com autenticação segura (ex: via VPN) a parceiros externos, fornecedores ou clientes.', f: 'A Intranet funciona sem o protocolo TCP/IP e não permite o uso de navegadores web.', exp: 'Internet = pública mundial; Intranet = privada interna (mesma tecnologia TCP/IP); Extranet = extensão controlada da Intranet para parceiros externos.' },
    { sub: 'Modelos de Referência: OSI (7 Camadas) vs. Arquitetura TCP/IP (4 ou 5 Camadas)', ref: 'Modelos OSI e TCP/IP', t: 'O modelo OSI divide-se em 7 camadas (1-Física, 2-Enlace, 3-Rede, 4-Transporte, 5-Sessão, 6-Apresentação, 7-Aplicação); na camada de Rede (3) operam o protocolo IP e os Roteadores (endereçamento lógico IP), na camada de Enlace (2) operam os Switches e o endereço físico MAC, e na camada de Transporte (4) operam os protocolos TCP (orientado à conexão, confiável) e UDP (não orientado à conexão, rápido, usado em DNS/streaming).', f: 'O protocolo UDP garante a entrega ordenada de todos os pacotes com confirmação de recebimento (three-way handshake).', exp: 'TCP = orientado à conexão (three-way handshake: SYN, SYN-ACK, ACK), controle de fluxo e retransmissão. UDP = sem conexão, menor overhead, sem garantia de entrega.' },
    { sub: 'Endereçamento IPv4 (32 bits) vs. IPv6 (128 bits) e NAT / DHCP', ref: 'IPv4 e IPv6', t: 'O endereço IPv4 possui 32 bits (4 octetos decimais separados por pontos, ex: 192.168.1.1), enquanto o IPv6 possui 128 bits (8 grupos de 4 dígitos hexadecimais separados por dois-pontos); o protocolo DHCP atribui endereços IP automaticamente na rede, e o DNS traduz nomes de domínio (URLs) em endereços IP.', f: 'O endereço IPv6 possui 64 bits representados exclusivamente em números binários separados por vírgulas.', exp: 'IPv4 = 32 bits ($2^{32} \\approx 4{,}3$ bilhões de endereços, decimais com ponto). IPv6 = 128 bits ($2^{128}$ endereços, hexadecimais de 0 a F com dois-pontos).' },
    { sub: 'Principais Protocolos da Camada de Aplicação e Portas Padrão', ref: 'Protocolos e Portas TCP/IP', t: 'Na camada de Aplicação: HTTP (porta 80) e HTTPS (porta 443, com TLS/SSL) transferem páginas web; FTP (portas 20 dados / 21 controle) transfere arquivos; SSH (porta 22) provê acesso remoto criptografado (substituindo o inseguro Telnet, porta 23); e DNS (porta 53) resolve nomes em IPs.', f: 'O protocolo Telnet (porta 23) criptografa todas as senhas com chave assimétrica de 256 bits.', exp: 'Telnet (23) e HTTP (80) trafegam em texto claro (sem criptografia); SSH (22) e HTTPS (443) trafegam com criptografia!' },
    { sub: 'Utilitários de Diagnóstico de Rede (ping, tracert/traceroute, ipconfig, nslookup)', ref: 'Comandos de Rede', t: 'O comando "ping" utiliza pacotes ICMP (Echo Request / Echo Reply) para testar a conectividade e medir o tempo de resposta (latência) até um host; "tracert" (no Windows) mostra a rota (saltos de roteadores) até o destino; e "ipconfig" exibe as configurações de IP da máquina local (sendo "ipconfig /flushdns" usado para limpar o cache DNS).', f: 'O comando "ping" transfere arquivos executáveis entre dois servidores utilizando a porta 21 do FTP.', exp: 'ping = testa conectividade/latência (ICMP); tracert = rastreia saltos de roteadores; ipconfig = mostra IP/máscara/gateway no Windows (ifconfig/ip addr no Linux).' }
  ],
  3: [
    { sub: 'Atalhos Universais dos Navegadores (Chrome, Edge e Firefox)', ref: 'Navegadores Web (FGV)', t: 'Nos principais navegadores (Google Chrome, Microsoft Edge e Mozilla Firefox): Ctrl + T abre nova guia; Ctrl + W (ou Ctrl + F4) fecha a guia atual; Ctrl + Shift + T reabre a última guia fechada; Ctrl + H abre o Histórico; Ctrl + J abre os Downloads; Ctrl + D adiciona a página atual aos Favoritos; e F11 alterna o modo de Tela Cheia.', f: 'Nos navegadores modernos, o atalho Ctrl + Shift + T apaga definitivamente todo o histórico de navegação do computador.', exp: 'Trio clássico de guias na FGV: Ctrl + T (nova guia), Ctrl + W (fecha guia), Ctrl + Shift + T (reabre a última guia fechada). E para mudar de guia: Ctrl + Tab (próxima) / Ctrl + Shift + Tab (anterior).' },
    { sub: 'Navegação Anônima / InPrivate / Privativa: O que é e o que NÃO é salvo', ref: 'Modo Anônimo / InPrivate', t: 'Ao navegar no modo Anônimo (Chrome: Ctrl + Shift + N) ou InPrivate (Edge: Ctrl + Shift + N) ou Privativo (Firefox: Ctrl + Shift + P), o navegador NÃO salva no computador local o histórico de navegação, os cookies/dados de sites da sessão nem as informações inseridas em formulários; porém, os arquivos baixados (Downloads) e os Favoritos criados SÃO mantidos, e o provedor de internet/empregador/site visitado continua vendo o acesso!', f: 'O modo de navegação anônima oculta o endereço IP do computador perante o provedor de internet e impede que a rede da empresa saiba quais sites foram acessados.', exp: 'Pegadinha campeã da FGV! Navegação anônima só impede o registro local no navegador após fechar a janela (mas mantém Downloads e Favoritos e NÃO esconde o tráfego do provedor, roteador da empresa ou sites)!' },
    { sub: 'Cookies, Cache do Navegador e Ctrl + F5 (Hard Refresh)', ref: 'Cookies e Cache', t: 'Cookies são pequenos arquivos de texto gravados pelos sites no navegador para identificar preferências, manter sessões autenticadas ou rastrear hábitos (cookies de terceiros); já o Cache armazena localmente cópias de imagens, folhas de estilo (CSS) e scripts para acelerar carregamentos futuros (sendo o atalho Ctrl + F5 usado para recarregar a página ignorando o cache local).', f: 'Os cookies são programas executáveis maliciosos que formatam automaticamente o disco rígido ao abrir uma página HTML.', exp: 'Cookies = pequenos arquivos de texto de sessão/preferências/rastreamento (não são vírus); Cache = cópias temporárias de arquivos da página para abrir mais rápido.' },
    { sub: 'Estrutura de uma URL (Esquema/Protocolo, Domínio, Porta, Caminho, Query String e Âncora)', ref: 'Anatomia da URL', t: 'Em uma URL completa como "https://www.sefaz.ba.gov.br:443/concurso/edital.pdf?ano=2026#vagas", "https" é o protocolo (esquema), "www.sefaz.ba.gov.br" é o FQDN (domínio), ":443" é a porta, "/concurso/edital.pdf" é o caminho do recurso, "?ano=2026" são os parâmetros (query string) e "#vagas" é o fragmento (âncora interna da página).', f: 'Na URL "https://www.sefaz.ba.gov.br", o sufixo ".br" indica que o servidor físico está obrigatoriamente desconectado da Internet.', exp: '.gov.br = domínio governamental brasileiro (ccTLD .br); #ancora = rola a página diretamente para a seção interna sem recarregar do servidor.' },
    { sub: 'Mecanismos de Busca Avançada (Operadores do Google / Bing)', ref: 'Operadores de Busca (FGV)', t: 'Nos motores de busca (Google): aspas duplas ("termo exato") buscam a expressão exata na ordem digitada; o sinal de menos colado à palavra (-termo) exclui resultados que contenham a palavra; "site:sefaz.ba.gov.br" restringe a busca àquele domínio específico; e "filetype:pdf" (ou "ext:pdf") restringe a busca a arquivos com aquela extensão.', f: 'Para buscar apenas arquivos em formato PDF no Google, deve-se digitar o operador "@formato=pdf*".', exp: 'Operadores de busca mais cobrados pela FGV: "frase exata" (aspas), -excluir (hífen colado), site:dominio, filetype:pdf, intitle:palavra.' }
  ],
  4: [
    { sub: 'Protocolos de Correio Eletrônico: SMTP (Envio) vs. POP3 e IMAP (Recebimento)', ref: 'Protocolos de E-mail', t: 'O protocolo SMTP (Simple Mail Transfer Protocol, portas 25 ou 587 com submissão autenticada / 465 SSL) é utilizado exclusivamente para o ENVIO (saída) de mensagens de correio eletrônico; já os protocolos POP3 (portas 110 / 995 SSL) e IMAP (portas 143 / 993 SSL) são utilizados para o RECEBIMENTO (acesso à caixa de entrada).', f: 'O protocolo SMTP é responsável por baixar os e-mails da caixa de entrada do servidor para o celular do usuário.', exp: 'Mnemônico clássico: SMTP = "Sua Mensagem Está Partindo" (Envio, porta 587/25); POP3 e IMAP = Recebimento.' },
    { sub: 'Diferença Fundamental entre POP3 e IMAP', ref: 'POP3 vs. IMAP', t: 'Por padrão, o protocolo POP3 transfere (baixa) as mensagens do servidor para o dispositivo local e as remove do servidor (acesso offline em dispositivo único, embora permita configurar para manter cópia); já o protocolo IMAP mantém as mensagens armazenadas no servidor e sincroniza em tempo real pastas, status de lido/não lido e rascunhos entre múltiplos dispositivos (PC, smartphone, webmail).', f: 'O protocolo POP3 sincroniza nativamente todas as pastas criadas pelo usuário na nuvem entre cinco dispositivos simultâneos sem baixar os e-mails.', exp: 'POP3 = puxa para a máquina local (foco offline); IMAP = mantém e sincroniza tudo no servidor (foco multi-dispositivo).' },
    { sub: 'Campos de Destinatários: Para (To), Cc (Com Cópia) e Cco (Com Cópia Oculta / Bcc)', ref: 'Destinatários de E-mail (FGV)', t: 'Ao enviar um e-mail com destinatários nos campos Para (A), Cc (B) e Cco (C e D): todos os destinatários enxergam quem está em Para (A) e em Cc (B); porém, cada destinatário colocado em Cco (Cópia Oculta) permanece invisível para os demais destinatários (inclusive C não vê que D também estava em Cco!).', f: 'Dois destinatários colocados juntos no campo Cco (Cópia Oculta) conseguem ver os endereços de e-mail um do outro.', exp: 'Pegadinha clássica FGV! Se C e D estão em Cco: A e B só veem A e B; C vê A, B e ele mesmo (mas NÃO vê D); D vê A, B e ele mesmo (mas NÃO vê C)!' },
    { sub: 'Responder (Reply) vs. Responder a Todos (Reply All) vs. Encaminhar (Forward)', ref: 'Ações em Mensagens de E-mail', t: 'A opção "Responder" envia a resposta apenas ao remetente original; "Responder a Todos" envia ao remetente e a todos os visíveis em Para e Cc (jamais para quem estava em Cco); além disso, tanto em "Responder" quanto em "Responder a Todos", os arquivos ANEXOS da mensagem original NÃO são reenviados automaticamente, ao passo que em "Encaminhar" (Forward) os anexos originais SÃO incluídos!', f: 'Ao clicar em "Responder" a um e-mail que continha três arquivos em anexo, os três anexos são reenviados automaticamente de volta ao remetente.', exp: 'Outra questão favorita da FGV: Responder / Responder a Todos = NÃO leva os anexos originais (só o histórico do texto). Encaminhar = LEVA os anexos originais!' },
    { sub: 'Assinatura Digital e Criptografia em E-mails (S/MIME e PGP) e Webmail', ref: 'Segurança em E-mail', t: 'Em clientes corporativos de e-mail (como Microsoft Outlook ou Mozilla Thunderbird com S/MIME), assinar digitalmente uma mensagem garante autenticidade, integridade e não repúdio (mas a mensagem continua legível por qualquer um), enquanto criptografar a mensagem com a chave pública do destinatário garante a confidencialidade (sigilo).', f: 'Um endereço de e-mail válido pode conter espaços em branco e dois símbolos de arroba (@) simultaneamente.', exp: 'Formato padrão de e-mail: usuario@dominio.com.br (sem espaços em branco e com um único símbolo @).' }
  ],
  5: [
    { sub: 'Seleção Rápida de Texto com o Mouse e Teclado no Microsoft Word', ref: 'Microsoft Word (FGV)', t: 'No corpo do texto do Microsoft Word: um duplo clique com o botão esquerdo sobre uma palavra seleciona a PALAVRA; um clique triplo seleciona todo o PARÁGRAFO; já na margem esquerda (barra de seleção): 1 clique seleciona a linha, 2 cliques selecionam o parágrafo e 3 cliques selecionam o documento inteiro (equivalente ao atalho Ctrl + T no Word em português!).', f: 'No Microsoft Word em português, o atalho para selecionar todo o documento é Ctrl + A, enquanto Ctrl + S salva o arquivo.', exp: 'Cuidado extremo com atalhos do Word EM PORTUGUÊS na FGV: Selecionar Tudo = Ctrl + T; Salvar = Ctrl + B; Sublinhar = Ctrl + S; Negrito = Ctrl + N; Itálico = Ctrl + I; Imprimir = Ctrl + P; Localizar = Ctrl + L; Substituir = Ctrl + U; Justificar = Ctrl + J; Centralizar = Ctrl + E!' },
    { sub: 'Pincel de Formatação (Clonar Formatação: 1 Clique vs. Duplo Clique)', ref: 'Guia Página Inicial do Word', t: 'A ferramenta Pincel de Formatação (na guia Página Inicial, atalhos Ctrl + Shift + C para copiar a formatação e Ctrl + Shift + V para colar a formatação) copia os atributos visuais de fonte e parágrafo de um trecho; se acionada com UM clique simples, aplica a formatação uma única vez e desativa; se acionada com DUPLO CLIQUE, permanece ativa para aplicar em múltiplos trechos até pressionar Esc.', f: 'O Pincel de Formatação copia o conteúdo textual da palavra selecionada e substitui as palavras seguintes pelo mesmo texto.', exp: 'O Pincel de Formatação copia a FORMA (fonte, tamanho, cor, negrito, alinhamento), nunca o texto em si!' },
    { sub: 'Quebra de Página (Ctrl + Enter) vs. Quebra de Seção (Próxima Página / Contínua)', ref: 'Guia Layout - Quebras no Word', t: 'Enquanto a Quebra de Página simples (atalho Ctrl + Enter) apenas encerra a página atual e inicia a próxima mantendo as mesmas configurações, a Quebra de Seção (guia Layout > Quebras) divide o documento em seções independentes, sendo INDISPENSÁVEL quando se deseja ter uma página em orientação Retrato e outra em Paisagem, ou cabeçalhos/rodapés e numerações diferentes no mesmo arquivo.', f: 'Para colocar apenas a página 4 de um documento Word na orientação Paisagem mantendo as demais em Retrato, basta inserir uma quebra de linha simples (Shift + Enter).', exp: 'Questão clássica FGV: mudar orientação (Retrato/Paisagem), margens, colunas ou cabeçalhos diferentes em partes do mesmo documento exige QUEBRA DE SEÇÃO (e desmarcar "Vincular ao Anterior" no cabeçalho)!' },
    { sub: 'Controle de Alterações (Track Changes) e Comentários na Guia Revisão', ref: 'Guia Revisão do Word', t: 'Na guia Revisão do Microsoft Word, o recurso "Controlar Alterações" (atalho Ctrl + Shift + E) registra todas as inserções, exclusões e mudanças de formatação feitas no documento para que o autor possa posteriormente Aceitar ou Rejeitar cada modificação; já o verificador de Ortografia e Gramática é acionado pela tecla F7.', f: 'No Microsoft Word, uma palavra sublinhada com uma linha ondulada vermelha indica que ela está formatada em estilo de título de sumário.', exp: 'Ondulado Vermelho = erro de ortografia (palavra não reconhecida); Ondulado Azul (ou duplo azul/verde) = possível desvio gramatical, de concordância ou de pontuação.' },
    { sub: 'Mala Direta (Guia Correspondências) e Sumário Automático (Guia Referências)', ref: 'Guias Correspondências e Referências', t: 'O recurso de Mala Direta (guia Correspondências) permite gerar cartas, etiquetas, envelopes ou e-mails personalizados em lote combinando um documento principal no Word com uma lista de destinatários (ex: planilha do Excel); já o Sumário Automático (guia Referências) é gerado automaticamente a partir dos parágrafos formatados com os Estilos de Título (Título 1, Título 2, Título 3).', f: 'Para gerar um Sumário Automático no Word, o usuário deve digitar manualmente os pontilhados e o número de cada página.', exp: 'Sumário Automático, Nota de Rodapé (Alt + Ctrl + F), Citações e Legendas ficam na guia REFERÊNCIAS; Mala Direta fica na guia CORRESPONDÊNCIAS.' }
  ],
  6: [
    { sub: 'Referências Relativas (A1), Absolutas ($A$1) e Mistas ($A1 ou A$1) no Excel', ref: 'Microsoft Excel - Referências', t: 'No Microsoft Excel, o símbolo de cifrão ($) trava a coordenada que vem imediatamente após ele quando a fórmula é copiada/arrastada pela alça de preenchimento: em A1 (relativa), variam coluna e linha; em $A$1 (absoluta, atalho F4), coluna e linha ficam fixas; em $A1, a coluna A fica fixa e a linha varia; e em A$1, a coluna varia e a linha 1 fica fixa.', f: 'Se a célula B1 contém a fórmula =$A1+10 e for copiada para a célula D5, a fórmula em D5 passará a ser =$C5+10.', exp: 'Como em =$A1 a coluna tem cifrão ($A), a coluna NUNCA muda ao copiar para os lados! Ao copiar de B1 para D5 (desceu 4 linhas), vira =$A5+10.' },
    { sub: 'Precedência de Operadores e Diferença entre Dois-Pontos (:) e Ponto e Vírgula (;)', ref: 'Operadores e Intervalos no Excel', t: 'Nos argumentos de funções do Excel: o operador dois-pontos (:) significa "ATÉ" (intervalo contínuo retangular, ex: A1:B3 abrange 6 células: A1, A2, A3, B1, B2, B3), enquanto o ponto e vírgula (;) significa "E" (união de referências separadas, ex: A1;B3 abrange apenas 2 células: A1 e B3). Na aritmética, a precedência é: Parênteses () -> Negação/Porcentagem -> Exponenciação (^) -> Multiplicação (*) e Divisão (/) (na ordem da esquerda p/ direita) -> Adição (+) e Subtração (-).', f: 'Na fórmula =10+2*3^2 do Excel, soma-se primeiro 10+2 para depois multiplicar por 3 e elevar ao quadrado.', exp: 'Calculando =10+2*3^2 pela precedência: 1º potência ($3^2 = 9$); 2º multiplicação ($2 \\times 9 = 18$); 3º soma ($10 + 18 = 28$)!' },
    { sub: 'Funções Estatísticas e Condicionais (MÉDIA, MED, MODO, MAIOR, MENOR, SE, SOMASE, CONT.SE)', ref: 'Funções Clássicas do Excel (FGV)', t: 'No Excel em português: =MÉDIA(A1:A5) calcula a média aritmética; =MED(A1:A5) calcula a MEDIANA; =MAIOR(intervalo; k) retorna o k-ésimo maior valor (diferente de =MÁXIMO, que retorna apenas o 1º maior); =CONT.NÚM conta células que contêm números; =CONT.VALORES conta células não vazias; =CONT.SE(intervalo; critério) conta sob condição; e =SOMASE(intervalo_critério; critério; [intervalo_soma]) soma sob condição.', f: 'A função =MED(10; 20; 90) no Excel retorna a média aritmética simples igual a 40.', exp: 'Pegadinha clássica FGV: no Excel, média aritmética é =MÉDIA(), enquanto =MED() calcula a MEDIANA (para 10, 20 e 90, =MED retorna 20)!' },
    { sub: 'Funções de Pesquisa e Referência: PROCV, PROCH, ÍNDICE/CORRESP e PROCX', ref: 'PROCV e PROCX no Excel', t: 'Na função =PROCV(valor_procurado; matriz_tabela; núm_índice_coluna; [procurar_intervalo]), a busca ocorre sempre na PRIMEIRA coluna à esquerda da matriz_tabela e retorna o valor da coluna indicada; o 4º argumento FALSO (ou 0) exige correspondência EXATA, enquanto VERDADEIRO (ou 1, ou omitido) faz busca aproximada (exigindo 1ª coluna ordenada). Já a moderna função =PROCX permite buscar em qualquer direção (inclusive da direita para a esquerda) e tem busca exata por padrão.', f: 'Na função PROCV, quando o quarto argumento é preenchido com 0 (ou FALSO), o Excel realiza uma busca aproximada.', exp: 'No PROCV: 0 (FALSO) = busca EXATA; 1 (VERDADEIRO ou omitido) = busca APROXIMADA.' },
    { sub: 'Códigos de Erro do Excel (#DIV/0!, #VALOR!, #NOME?, #REF!, #N/D, #####)', ref: 'Erros no Excel', t: 'No Excel: #DIV/0! indica divisão por zero ou célula vazia; #VALOR! indica tipo de argumento incompatível (ex: somar texto com o operador +: ="casa"+5, embora =SOMA("casa"; 5) ignore o texto na célula); #NOME? indica nome de função digitado errado (ex: =MEDIA sem acento em versões antigas ou nome inexistente); #REF! indica referência inválida (ex: linha/coluna da fórmula foi excluída); #N/D indica valor não encontrado no PROCV; e ##### indica que a coluna é estreita demais para exibir o número (ou data negativa).', f: 'O aviso ##### em uma célula numérica indica que a fórmula contém um erro irreversível de sintaxe matemática.', exp: '##### não é erro de cálculo: basta aumentar a largura da coluna para o número aparecer!' }
  ],
  7: [
    { sub: 'Modos de Exibição e Slide Mestre no Microsoft PowerPoint', ref: 'Microsoft PowerPoint', t: 'No Microsoft PowerPoint (guia Exibição), o recurso "Slide Mestre" armazena o tema, as fontes, os planos de fundo e o posicionamento de logotipos no topo da hierarquia: qualquer alteração feita no Slide Mestre reflete automaticamente em todos os slides da apresentação que utilizam aquele layout.', f: 'Para inserir o logotipo da SEFAZ-BA no canto superior de 80 slides de forma padronizada, é impossível usar o Slide Mestre, devendo-se colar um por um.', exp: 'Slide Mestre (guia Exibição) = altera globalmente o padrão visual, fontes e logotipo de todos os slides de uma só vez!' },
    { sub: 'Transições (Entre Slides) vs. Animações (Objetos Dentro do Slide)', ref: 'Guias Transições e Animações', t: 'No PowerPoint, os efeitos visuais dividem-se em duas guias distintas: TRANSIÇÕES são os efeitos de movimento que ocorrem na passagem de um slide inteiro para o próximo slide; já ANIMAÇÕES (de Entrada, Ênfase, Saída e Trajetórias de Animação) são aplicadas a objetos individuais DENTRO de um slide (textos, formas, gráficos, imagens).', f: 'A guia Transições aplica efeitos de entrada e saída apenas a palavras isoladas dentro de uma caixa de texto.', exp: 'Transição = passagem de um SLIDE para outro; Animação = movimento de um OBJETO dentro do slide.' },
    { sub: 'Teclas de Atalho da Apresentação de Slides (F5, Shift + F5, B/P, W/C, Esc)', ref: 'Atalhos do PowerPoint (FGV)', t: 'No Microsoft PowerPoint: a tecla F5 inicia a apresentação de slides desde o PRIMEIRO slide (do começo); o atalho Shift + F5 inicia a apresentação a partir do SLIDE ATUAL; o atalho Ctrl + M insere um NOVO SLIDE (enquanto Ctrl + N cria uma nova apresentação em branco!); e durante a apresentação, pressionar P (ou ponto) escurece a tela (preta), C (ou vírgula) clareia (branca) e Esc encerra.', f: 'No PowerPoint, o atalho Ctrl + M aplica a formatação de fonte em itálico no texto selecionado.', exp: 'Pegadinha clássica FGV no PowerPoint: Novo Slide = Ctrl + M! (Nova Apresentação = Ctrl + N; Duplicar slide = Ctrl + D; Iniciar do começo = F5; Iniciar do slide atual = Shift + F5).' },
    { sub: 'Modo de Exibição do Apresentador e Anotações do Orador', ref: 'Modo do Apresentador', t: 'Quando o computador está conectado a um segundo monitor ou projetor, o "Modo de Exibição do Apresentador" permite que o público veja apenas o slide em tela cheia no projetor, enquanto o palestrante visualiza na tela do seu notebook o slide atual, a prévia do próximo slide, o cronômetro e as suas Anotações de Orador.', f: 'As anotações digitadas no painel de Anotações do PowerPoint aparecem automaticamente projetadas em letras gigantes sobre o slide para o público.', exp: 'O painel de Anotações serve como roteiro para o apresentador (visível no Modo do Apresentador e na impressão de Anotações, mas invisível para a plateia no telão).' },
    { sub: 'Formatos de Arquivo do PowerPoint (.pptx, .ppsx, .potx e Exportação PDF/Vídeo)', ref: 'Extensões do PowerPoint', t: 'No PowerPoint: a extensão padrão de apresentação editável é .pptx (ou .pptm com macros); a extensão .potx corresponde a um Modelo (Template) do PowerPoint; e a extensão .ppsx corresponde a uma Apresentação de Slides do PowerPoint que, ao receber duplo clique no Windows Explorer, abre diretamente em modo de exibição de tela cheia (sem abrir a tela de edição).', f: 'Um arquivo salvo com a extensão .ppsx é uma planilha eletrônica exclusiva do Microsoft Excel.', exp: '.pptx = Apresentação editável; .ppsx = Apresentação de Slides (abre direto no show); .potx = Modelo (Template).' }
  ],
  8: [
    { sub: 'Tríade CIA + Autenticidade e Não Repúdio (Irretratabilidade) na Segurança da Informação', ref: 'Princípios da Segurança (DICAI)', t: 'Os pilares fundamentais da Segurança da Informação (mnemônico DICA/DICAI) são: Confidencialidade (acesso apenas por pessoas autorizadas), Integridade (garantia de que a informação não foi alterada indevidamente), Disponibilidade (acesso sempre que necessário pelos usuários autorizados), Autenticidade (identificação verdadeira da origem/autor) e Não Repúdio / Irretratabilidade (impossibilidade de o autor negar a autoria de um ato assinado digitalmente).', f: 'O princípio da Disponibilidade garante que nenhum arquivo possa ser lido pelo próprio dono sem autorização judicial.', exp: 'Criptografia protege a Confidencialidade; Hash protege a Integridade; Backup/Redundância/No-break protegem a Disponibilidade; Assinatura Digital protege Autenticidade, Integridade e Não Repúdio.' },
    { sub: 'Diferença entre Vírus, Worm (Verme) e Bot / Zumbi', ref: 'Malwares Clássicos (CERT.br)', t: 'O Vírus precisa de um arquivo hospedeiro e exige a execução (ação do usuário) para se propagar; já o Worm (verme) é um programa autônomo que NÃO precisa de arquivo hospedeiro nem de ação do usuário, propagando-se automaticamente pela rede explorando vulnerabilidades; e o Bot (semelhante ao worm na propagação) permite que o invasor controle remotamente a máquina infectada (Zumbi), formando uma rede de computadores escravos chamada Botnet (usada em ataques DDoS).', f: 'O Worm depende obrigatoriamente de ser anexado a uma planilha do Excel e clicado manualmente pelo usuário para se replicar.', exp: 'Diferença campeã de provas (Cartilha CERT.br): Vírus = precisa de hospedeiro + execução pelo usuário; Worm = autônomo, propaga-se sozinho pela rede explorando falhas.' },
    { sub: 'Cavalo de Troia (Trojan), Spyware (Keylogger vs. Screenlogger), Backdoor e Rootkit', ref: 'Trojan, Spyware e Rootkit', t: 'O Trojan (Cavalo de Troia) entra disfarçado de programa legítimo/útil (jogos, cartões, ativadores), não se replica sozinho e executa funções maliciosas ocultas (como abrir um Backdoor - porta dos fundos); o Spyware monitora atividades da vítima, dividindo-se em Keylogger (captura tudo o que é digitado no teclado) e Screenlogger (fotografa a tela ao redor do clique do mouse para burlar teclados virtuais); e o Rootkit é um conjunto de ferramentas que esconde a presença do invasor/malware do sistema operacional e do antivírus.', f: 'O uso do teclado virtual bancário na tela impede a captura da senha por um malware do tipo Screenlogger.', exp: 'Keylogger = captura teclado físico; Screenlogger = printa a tela onde o mouse clica (criado especificamente para roubar senhas digitadas em teclados virtuais!).' },
    { sub: 'Ransomware (Crypto vs. Locker)', ref: 'Ransomware (Sequestro de Dados)', t: 'O Ransomware é o código malicioso que torna inacessíveis os dados armazenados no equipamento (geralmente usando criptografia forte - Ransomware Crypto - ou bloqueando a tela do sistema - Ransomware Locker) e exige o pagamento de um resgate financeiro (ransom, comumente em criptomoedas como Bitcoin) para restabelecer o acesso; a principal defesa preventiva para recuperação sem pagar resgate é o Backup atualizado e isolado (offline/imutável).', f: 'O Ransomware tem como único objetivo exibir propagandas comerciais não solicitadas no navegador (Adware).', exp: 'Ransomware = sequestro de dados mediante criptografia + cobrança de resgate (ransom). Adware = exibe anúncios.' },
    { sub: 'Engenharia Social: Phishing, Spear Phishing, Whaling, Vishing, Smishing e Pharming', ref: 'Golpes na Internet (CERT.br)', t: 'O Phishing utiliza mensagens fraudulentas (e-mails, links falsos imitando bancos ou órgãos públicos) para induzir a vítima a fornecer dados confidenciais; quando é altamente personalizado para um alvo específico chama-se Spear Phishing (e se o alvo for um alto executivo/CEO, Whaling); por SMS chama-se Smishing; por voz/telefone chama-se Vishing; já o Pharming corrompe o servidor DNS (DNS Cache Poisoning) para redirecionar o usuário para um site falso mesmo que ele digite a URL correta no navegador!', f: 'No ataque de Pharming, o criminoso liga por telefone para a vítima fingindo ser gerente do banco.', exp: 'Phishing = isca genérica por e-mail/link; Spear Phishing = alvo específico; Whaling = alto executivo ("baleia"); Smishing = SMS; Vishing = Voz; Pharming = envenenamento de DNS.' }
  ],
  9: [
    { sub: 'Firewall (Filtro de Pacotes e Proxy) vs. Antivírus / EDR e IDS vs. IPS', ref: 'Mecanismos de Defesa', t: 'O Firewall é uma barreira de segurança que controla e filtra o tráfego de rede que entra e sai (com base em regras de portas, protocolos e IPs), mas NÃO remove vírus já instalados nem impede que o usuário baixe um vírus por uma porta permitida (função do Antivírus/Antimalware); já o IDS (Intrusion Detection System) apenas detecta e alerta sobre intrusões, enquanto o IPS (Intrusion Prevention System) detecta e BLOQUEIA ativamente o ataque.', f: 'O Firewall do Windows substitui integralmente o antivírus, pois escaneia e desinfecta pendrives sem conexão de rede.', exp: 'Firewall = porteiro do tráfego de rede (regras de portas/IPs); Antivírus = inspeciona arquivos/memória em busca de assinaturas e comportamentos maliciosos.' },
    { sub: 'Criptografia Simétrica (Chave Única) vs. Criptografia Assimétrica (Chave Pública e Privada)', ref: 'Criptografia', t: 'Na Criptografia Simétrica (ex: AES, DES, 3DES), utiliza-se uma ÚNICA chave secreta compartilhada tanto para cifrar quanto para decifrar a mensagem (muito mais rápida, ideal para grandes volumes de dados); já na Criptografia Assimétrica (ex: RSA, ECC), cada usuário possui um PAR de chaves matematicamente vinculadas: uma Chave Pública (divulgada a todos) e uma Chave Privada (secreta, guardada apenas pelo titular).', f: 'Na criptografia assimétrica RSA, utiliza-se a mesma chave pública tanto para cifrar quanto para decifrar o documento.', exp: 'Simétrica = 1 chave compartilhada (rápida, mas tem o problema da troca da chave); Assimétrica = 2 chaves (Pública + Privada).' },
    { sub: 'Confidencialidade vs. Assinatura Digital na Criptografia Assimétrica', ref: 'Uso das Chaves Pública e Privada (FGV)', t: 'Na criptografia assimétrica, o uso do par de chaves depende do objetivo: (1) para garantir CONFIDENCIALIDADE (sigilo), o remetente cifra a mensagem com a CHAVE PÚBLICA DO DESTINATÁRIO, de modo que só o destinatário (com sua chave privada) possa abri-la; (2) para gerar uma ASSINATURA DIGITAL (autenticidade, integridade e não repúdio), o remetente cifra o resumo (hash) com a SUA PRÓPRIA CHAVE PRIVADA, e qualquer pessoa confere usando a chave pública do remetente!', f: 'Para assinar digitalmente uma nota fiscal eletrônica, o contribuinte utiliza a chave pública da Secretaria da Fazenda.', exp: 'Regra de ouro da FGV (cai em toda prova!): Sigilo/Confidencialidade = cifra com a Chave PÚBLICA do Destinatário. Assinatura Digital = assina com a Chave PRIVADA do Remetente!' },
    { sub: 'Função Hash (Resumo Criptográfico) e Certificado Digital (ICP-Brasil)', ref: 'Hash e ICP-Brasil', t: 'A função Hash (ex: SHA-256, MD5) é um algoritmo unidirecional (irreversível) que transforma um documento de qualquer tamanho em uma sequência de tamanho fixo (resumo/digest) para verificar a INTEGRIDADE (se mudar uma vírgula no texto, o hash muda completamente); já o Certificado Digital ICP-Brasil (emitido por uma Autoridade Certificadora - AC) vincula a chave pública à identidade do titular, sendo do tipo A1 (arquivo em software, validade de 1 ano) ou A3 (mídia física criptográfica como Token USB ou Smartcard, validade de até 5 anos).', f: 'A partir do resumo gerado por uma função Hash SHA-256, é possível descriptografar e reconstruir o documento original de 500 páginas.', exp: 'Função Hash NÃO é reversível (é unidirecional, serve para Integridade). Certificado A1 = software (1 ano); A3 = hardware Token/Cartão (1 a 5 anos).' },
    { sub: 'Política de Backup: Completo (Full), Incremental e Diferencial', ref: 'Tipos de Backup (FGV)', t: 'O Backup Completo (Normal/Full) copia todos os arquivos selecionados e limpa o atributo de arquivamento (marca como copiado); o Backup INCREMENTAL copia apenas os arquivos criados ou alterados desde o último backup (seja ele completo ou incremental) e LIMPA o atributo (é o mais rápido para fazer o backup, mas o mais lento para restaurar, pois exige o Full + todos os incrementais em sequência); já o Backup DIFERENCIAL copia tudo o que mudou desde o último Completo e NÃO limpa o atributo (na restauração, exige apenas o último Full + o último Diferencial!).', f: 'Para restaurar um sistema que utiliza backup diferencial diário, é necessário restaurar o backup completo de domingo mais todos os backups diferenciais de segunda a sexta.', exp: 'Diferença clássica FGV: Incremental = rápido p/ gravar (acumula pouco), lento p/ restaurar (Full + TODOS os incrementais). Diferencial = acumula desde o Full (não marca o bit), rápido p/ restaurar (Full + SÓ o último diferencial)!' }
  ],
  10: [
    { sub: 'Modelos de Serviço em Nuvem: IaaS, PaaS e SaaS (NIST)', ref: 'Cloud Computing - Modelos de Serviço', t: 'Segundo o NIST, os três modelos fundamentais de serviço em nuvem são: (1) IaaS (Infraestrutura como Serviço: o usuário aluga servidores virtuais, rede e armazenamento brutos, gerenciando o SO e aplicações, ex: AWS EC2, Azure VMs, Google Compute Engine); (2) PaaS (Plataforma como Serviço: ambiente pronto para desenvolvedores criarem e hospedarem aplicações com banco de dados/runtime, sem gerenciar o SO subjacente, ex: Google App Engine, Heroku); e (3) SaaS (Software como Serviço: aplicativo pronto consumido pelo usuário final via navegador/app, ex: Gmail, Google Docs, Microsoft 365, Dropbox).', f: 'O uso do webmail Gmail e do Google Drive pelo usuário final classifica-se como Infraestrutura como Serviço (IaaS).', exp: 'Público-alvo de cada modelo: IaaS = Arquitetos de Rede/Infraestrutura; PaaS = Desenvolvedores de Software; SaaS = Usuário Final.' },
    { sub: 'Modelos de Implantação de Nuvem: Pública, Privada, Híbrida e Comunitária', ref: 'Modelos de Implantação', t: 'A Nuvem Pública pertence a um provedor terceirizado (AWS, Azure, GCP) que compartilha a infraestrutura física entre múltiplos clientes (multitenancy); a Nuvem Privada tem infraestrutura dedicada exclusivamente a uma única organização (local ou terceirizada); a Nuvem Comunitária é compartilhada por várias organizações com interesses/missões comuns (ex: órgãos de um governo estadual); e a Nuvem Híbrida combina duas ou mais nuvens distintas (ex: privada + pública) unidas por tecnologia que permite portabilidade de dados e aplicações.', f: 'Na Nuvem Pública, todos os dados armazenados pelas empresas ficam abertos para consulta pública gratuita de qualquer cidadão na Internet.', exp: 'Pegadinha clássica: Nuvem "Pública" refere-se ao compartilhamento comercial da infraestrutura do provedor (com isolamento lógico seguro entre os clientes), e NÃO a "dados abertos ao público"!' },
    { sub: 'Cinco Características Essenciais da Computação em Nuvem (NIST SP 800-145)', ref: 'Características Essenciais do NIST', t: 'Segundo o NIST, a computação em nuvem possui 5 características essenciais: (1) Autoatendimento sob demanda (On-demand self-service); (2) Amplo acesso pela rede (Broad network access); (3) Agrupamento de recursos (Resource pooling - multitenancy); (4) Elasticidade rápida (Rapid elasticity - escalar para cima ou para baixo rapidamente conforme a demanda); e (5) Serviço medido (Measured service - pagamento pelo uso / pay-per-use).', f: 'Na computação em nuvem, a elasticidade rápida exige que o cliente compre servidores físicos com seis meses de antecedência.', exp: 'Elasticidade rápida permite aumentar (scale up / scale out) ou reduzir recursos computacionais automaticamente em minutos conforme o pico de acesso.' },
    { sub: 'Escalabilidade Vertical (Scale Up) vs. Escalabilidade Horizontal (Scale Out)', ref: 'Escalabilidade em Nuvem', t: 'Na escalabilidade vertical (Scale Up / Scale Down), aumenta-se a capacidade de um único servidor adicionando mais CPU, memória RAM ou disco àquela máquina; já na escalabilidade horizontal (Scale Out / Scale In), adicionam-se mais instâncias/servidores trabalhando em paralelo com balanceamento de carga (load balancing).', f: 'A escalabilidade horizontal consiste em trocar o pente de memória RAM de um único computador de mesa.', exp: 'Vertical (Scale Up) = máquina mais potente (+RAM/+CPU no mesmo servidor). Horizontal (Scale Out) = mais máquinas em paralelo (+servidores no cluster).' },
    { sub: 'Armazenamento em Nuvem e Sincronização (OneDrive, Google Drive, Dropbox)', ref: 'Armazenamento em Nuvem', t: 'O Microsoft OneDrive (integrado nativamente ao Windows 10/11) e o Google Drive oferecem armazenamento em nuvem (SaaS) com recurso de "Arquivos Sob Demanda": os arquivos aparecem listados no Explorador de Arquivos do PC (com ícone de nuvem azul indicando que ocupam zero espaço no disco local) e só são baixados quando abertos, a menos que marcados como "Sempre manter neste dispositivo" (ícone de círculo verde cheio).', f: 'Todos os arquivos armazenados no OneDrive ocupam obrigatoriamente o dobro do espaço no disco rígido local do notebook.', exp: 'Ícones do OneDrive no Windows: Nuvem azul = apenas online (não ocupa espaço no HD); Círculo branco com check verde = baixado localmente sob demanda; Círculo verde sólido com check branco = sempre disponível offline neste dispositivo.' }
  ],
  11: [
    { sub: 'Síntese FGV: Atalhos Contrastantes entre Word, Excel, PowerPoint e Navegadores', ref: 'Revisão Geral Informática FGV', t: 'Atenção máxima às diferenças de atalhos nas provas da FGV: (1) Selecionar Tudo é Ctrl + T no Word e no Excel em português, mas é Ctrl + A nos Navegadores e no Windows Explorer; (2) Salvar é Ctrl + B no Word e no Excel em português, mas Ctrl + S nos programas em inglês; (3) no PowerPoint, Ctrl + M cria um NOVO SLIDE e Ctrl + N cria uma nova apresentação; e (4) no Excel, F4 trava referências ($A$1) e F2 edita a célula ativa.', f: 'O atalho Ctrl + T funciona de maneira idêntica no Microsoft Word e no Google Chrome, abrindo uma nova guia em ambos.', exp: 'No Word (PT-BR): Ctrl + T = Selecionar Tudo; Ctrl + B = Salvar; Ctrl + S = Sublinhar; Ctrl + U = Substituir; Ctrl + L = Localizar. No Chrome/Edge: Ctrl + T = Nova Guia; Ctrl + W = Fechar Guia; Ctrl + Shift + T = Reabrir Guia; Ctrl + J = Downloads; Ctrl + H = Histórico.' },
    { sub: 'Síntese FGV: Fórmulas de Excel que Mais Caem (SE, SOMASE, PROCV, MED e Precedência)', ref: 'Revisão Geral Informática FGV', t: 'No Excel: (1) a exponenciação (^) precede a multiplicação/divisão (* /), que precedem a soma/subtração (+ -); (2) dois-pontos (A1:B3) indica intervalo contínuo (6 células) e ponto e vírgula (A1;B3) indica células isoladas (2 células); (3) =MED() calcula a mediana e =MÉDIA() calcula a média aritmética; e (4) =MAIOR(intervalo; k) exige o 2º argumento k, enquanto =MÁXIMO(intervalo) não tem o argumento k.', f: 'No Excel, a fórmula =MÁXIMO(A1:A10; 2) retorna o segundo maior valor do intervalo A1:A10.', exp: 'Cuidado! Em =MÁXIMO(A1:A10; 2), o número 2 é tratado como um valor numérico comparado com o intervalo! Para pegar o 2º maior valor do intervalo, a função obrigatória é =MAIOR(A1:A10; 2)!' },
    { sub: 'Síntese FGV: Correio Eletrônico (Protocolos, Cco e Anexos ao Responder)', ref: 'Revisão Geral Informática FGV', t: 'No correio eletrônico: (1) SMTP envia e POP3/IMAP recebem; (2) destinatários em Cco (Bcc) não são vistos por ninguém (nem por outros destinatários que também estejam em Cco); e (3) clicar em "Responder" ou "Responder a Todos" NÃO inclui os arquivos anexos originais, ao passo que "Encaminhar" inclui os anexos.', f: 'Ao utilizar "Responder a Todos", a resposta é enviada automaticamente também para todos os endereços que estavam em Cópia Oculta (Cco).', exp: 'Como os destinatários em Cco não constam no cabeçalho entregue ao destinatário que está respondendo, o "Responder a Todos" jamais atinge quem estava em Cco!' },
    { sub: 'Síntese FGV: Segurança da Informação (Malwares, Golpes, Criptografia e Backup)', ref: 'Revisão Geral Informática FGV', t: 'Em Segurança: (1) Vírus exige hospedeiro e execução, enquanto Worm propaga-se sozinho pela rede; (2) Ransomware sequestra dados com criptografia exigindo resgate; (3) Screenlogger fotografa a tela no clique do mouse; (4) Pharming envenena o DNS; (5) na criptografia assimétrica, cifra-se com a chave PÚBLICA do destinatário (sigilo) e assina-se com a chave PRIVADA do remetente (assinatura digital); e (6) na restauração de backup, o Diferencial exige apenas o Full + o último Diferencial, enquanto o Incremental exige o Full + todos os Incrementais.', f: 'Para garantir o sigilo de um documento confidencial enviado ao diretor, o auditor deve cifrá-lo com a sua própria chave privada.', exp: 'Se cifrar com a própria chave privada, qualquer pessoa que tem a chave pública abre (isso é Assinatura Digital, não sigilo)! Para sigilo, cifra-se com a Chave PÚBLICA do Destinatário!' },
    { sub: 'Síntese FGV: Redes, Windows e Computação em Nuvem', ref: 'Revisão Geral Informática FGV', t: 'No Windows 10/11: arrastar arquivo na mesma unidade move e em unidades diferentes copia; Shift + Delete exclui sem passar pela Lixeira; caracteres \\ / : * ? " < > | são proibidos em nomes de arquivos. Em Nuvem: IaaS = infraestrutura (VMs), PaaS = plataforma de desenvolvimento e SaaS = software pronto para o usuário final.', f: 'Ao arrastar um arquivo de uma pasta para outra dentro do mesmo disco C: sem pressionar teclas, o Windows cria uma cópia duplicada.', exp: 'Mesma letra de unidade (C: para C:) -> MOVE; Letras de unidades diferentes (C: para D:) -> COPIA.' }
  ]
};

export const IGUALDADE_RACIAL_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Repúdio ao Racismo e Igualdade Material na CF/88 (Arts. 3º, IV, 4º, VIII e 5º, XLII)', ref: 'CF/88, Arts. 3º, 4º e 5º', t: 'A Constituição Federal de 1988 estabelece a promoção do bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e quaisquer outras formas de discriminação, como objetivo fundamental da República (Art. 3º, IV), o repúdio ao terrorismo e ao racismo como princípio das relações internacionais (Art. 4º, VIII) e a prática do racismo como crime inafiançável e imprescritível, sujeito à pena de reclusão (Art. 5º, XLII).', f: 'Na Constituição Federal de 1988, o repúdio ao racismo figura apenas como norma programática sem sanção penal inafiançável.', exp: 'Atenção à distinção constitucional: Promover o bem sem preconceito = Objetivo Fundamental (Art. 3º, IV); Repúdio ao racismo = Princípio das Relações Internacionais (Art. 4º, VIII); Crime inafiançável, imprescritível e punido com reclusão = Direito e Garantia Individual (Art. 5º, XLII).' },
    { sub: 'Hierarquia dos Tratados Internacionais de Direitos Humanos (Art. 5º, §3º da CF/88 e STF)', ref: 'CF/88, Art. 5º, §3º', t: 'Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais (ex: Convenção de Nova York e Tratado de Marraquexe sobre deficiência e Convenção Interamericana contra o Racismo); já os aprovados pelo rito ordinário possuem status SUPRALEGAL (abaixo da CF e acima das leis ordinárias).', f: 'Qualquer tratado internacional de direitos humanos assinado pelo Presidente da República ingressa automaticamente no Brasil com status de norma originária.', exp: 'Importante para a SEFAZ-BA: a Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância foi aprovada pelo rito do Art. 5º, §3º (Decreto 10.932/2022) e tem status de EMENDA CONSTITUCIONAL!' },
    { sub: 'Características dos Direitos Humanos e Fundamentais', ref: 'Teoria Geral dos Direitos Humanos', t: 'Os direitos humanos e fundamentais caracterizam-se pela historicidade, universalidade, inalienabilidade, irrenunciabilidade, imprescritibilidade, indivisibilidade, interdependência, complementaridade e pela vedação ao retrocesso social (efeito cliquet), além de não serem absolutos (relatividade ou limitabilidade).', f: 'Os direitos fundamentais de primeira dimensão são absolutos e admitem renúncia definitiva mediante contrato particular.', exp: 'Nenhum direito fundamental é absoluto (nem mesmo o direito à vida, já que a CF/88 admite pena de morte em caso de guerra declarada).' },
    { sub: 'Dimensões (Gerações) dos Direitos Humanos e Igualdade Formal vs. Material', ref: 'Dimensões dos Direitos Fundamentais', t: 'Enquanto a igualdade formal (1ª dimensão - liberdade negativa perante a lei) trata todos de forma abstratamente idêntica, a igualdade material ou substancial (2ª e 3ª dimensões) exige tratar igualmente os iguais e desigualmente os desiguais na medida de suas desigualdades, fundamentando constitucionalmente as políticas de ação afirmativa.', f: 'O princípio constitucional da isonomia proíbe o Estado de instituir qualquer ação afirmativa voltada a grupos historicamente vulnerabilizados.', exp: 'No julgamento da ADPF 186 e da ADC 41, o STF consagrou que as ações afirmativas realizam a dimensão material do princípio da igualdade e a justiça distributiva/compensatória.' },
    { sub: 'Incidente de Deslocamento de Competência (IDC - Art. 109, §5º da CF/88)', ref: 'CF/88, Art. 109, §5º', t: 'Nas hipóteses de grave violação de direitos humanos, o Procurador-Geral da República, com a finalidade de assegurar o cumprimento de obrigações decorrentes de tratados internacionais de direitos humanos dos quais o Brasil seja parte, poderá suscitar, perante o Superior Tribunal de Justiça (STJ), em qualquer fase do inquérito ou processo, incidente de deslocamento de competência para a Justiça Federal.', f: 'O Incidente de Deslocamento de Competência é proposto pelo Defensor Público Estadual perante o Supremo Tribunal Federal.', exp: 'Legitimado exclusivo do IDC = Procurador-Geral da República (PGR); Tribunal competente para julgar o IDC = Superior Tribunal de Justiça (STJ).' }
  ],
  1: [
    { sub: 'Conceito de Discriminação Racial na Convenção da ONU de 1965 (CERD - Decreto 65.810/69)', ref: 'Convenção da ONU contra Discriminação Racial (CERD)', t: 'Na Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial (ONU, 1965), a expressão "discriminação racial" significa qualquer distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica que tenha por objeto ou efeito anular ou restringir o reconhecimento, gozo ou exercício em igualdade de condições dos direitos humanos e liberdades fundamentais.', f: 'A Convenção da ONU de 1965 considera discriminação racial apenas os atos que tenham intenção dolosa expressa, ignorando práticas que produzam efeito discriminatório indireto.', exp: 'Atenção: a Convenção abrange tanto o OBJETO (propósito/intenção - discriminação direta) quanto o EFEITO/RESULTADO (impacto desproporcional - discriminação indireta)!' },
    { sub: 'Medidas Especiais de Proteção (Ações Afirmativas) e Caráter Temporário na CERD (Art. 1º, §4º)', ref: 'CERD, Art. 1º, §4º', t: 'Segundo a Convenção da ONU (CERD), NÃO serão consideradas discriminação racial as medidas especiais tomadas com o único objetivo de assegurar o progresso adequado de certos grupos raciais ou étnicos, desde que tais medidas não conduzam à manutenção de direitos separados para diferentes grupos raciais e NÃO prossigam após terem sido alcançados os seus objetivos.', f: 'Segundo a Convenção da ONU sobre Eliminação da Discriminação Racial, as medidas especiais de ação afirmativa devem ser perpétuas e criar direitos separados permanentes.', exp: 'As medidas especiais (ações afirmativas) na CERD e na CEDAW são legítimas, não configuram discriminação e possuem natureza TEMPORÁRIA (cessam quando alcançados os objetivos de igualdade de oportunidade e tratamento).' },
    { sub: 'Órgão de Monitoramento da CERD e Comunicações Individuais (Art. 14)', ref: 'Comitê CERD da ONU', t: 'A Convenção de 1965 instituiu o Comitê para a Eliminação da Discriminação Racial (composto por 18 peritos independentes de alta moralidade e imparcialidade), que analisa relatórios periódicos dos Estados-partes, comunicações interestatais e, para os países que reconheceram sua competência (como o Brasil em 2002), petições/comunicações individuais de vítimas após o esgotamento dos recursos internos.', f: 'O Comitê para a Eliminação da Discriminação Racial da ONU tem poder para decretar prisão preventiva de chefes de Estado.', exp: 'O Comitê CERD (18 peritos) emite recomendações e pareceres (não é tribunal penal internacional).' },
    { sub: 'Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher (CEDAW, 1979)', ref: 'Convenção CEDAW (Decreto 4.377/2002)', t: 'A Convenção da ONU sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher (CEDAW, 1979) define discriminação contra a mulher como toda distinção, exclusão ou restrição baseada no sexo que tenha por objeto ou resultado prejudicar ou anular o exercício dos direitos humanos pela mulher, independentemente de seu estado civil, e autoriza medidas especiais de caráter temporário para acelerar a igualdade de fato entre homens e mulheres (Art. 4º).', f: 'A Convenção CEDAW considera que as disposições especiais de proteção à maternidade constituem discriminação ilegal contra os homens.', exp: 'Art. 4º da CEDAW: nem as medidas especiais temporárias (ações afirmativas de gênero) nem as medidas de proteção à maternidade são consideradas discriminatórias!' },
    { sub: 'Convenção Interamericana contra o Racismo (Status de Emenda Constitucional - Decreto 10.932/2022)', ref: 'Convenção Interamericana contra o Racismo', t: 'A Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância (adotada na Guatemala em 2013 e promulgada no Brasil com status de Emenda Constitucional) conceitua expressamente a discriminação racial indireta (quando uma disposição aparentemente neutra causa desvantagem particular a um grupo racial) e a discriminação múltipla ou agravada (interseccionalidade de dois ou mais fatores).', f: 'O Brasil recusou-se a ratificar a Convenção Interamericana contra o Racismo, que não possui vigência no território nacional.', exp: 'A Convenção Interamericana contra o Racismo é o 4º tratado no Brasil aprovado com rito de Emenda Constitucional (Art. 5º, §3º da CF/88) e traz os conceitos de discriminação indireta e discriminação múltipla/agravada!' }
  ],
  2: [
    { sub: 'Três Conceitos Fundamentais do Estatuto da Igualdade Racial (Lei 12.288/2010, Art. 1º, par. único)', ref: 'Lei 12.288/2010, Art. 1º, par. único', t: 'No Estatuto da Igualdade Racial Nacional (Lei 12.288/2010): (I) Discriminação racial ou étnico-racial é toda distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica; (II) Desigualdade racial é toda situação injustificada de diferenciação de acesso e fruição de bens, serviços e oportunidades, nas esferas pública e privada; e (III) Desigualdade de gênero e raça é a assimetria que acentua a distância social entre mulheres negras e os demais segmentos sociais.', f: 'Na Lei 12.288/2010, o conceito de população negra abrange exclusivamente os cidadãos que se autodeclaram pretos, excluindo os pardos.', exp: 'Art. 1º, parágrafo único, IV da Lei 12.288/2010: População Negra = o conjunto de pessoas que se autodeclaram PRETAS e PARDAS, conforme o quesito cor ou raça usado pelo IBGE, ou que adotam autodefinição análoga!' },
    { sub: 'Ações Afirmativas vs. Políticas Públicas no Estatuto da Igualdade Racial (Art. 1º, V e VI)', ref: 'Lei 12.288/2010, Art. 1º, V e VI', t: 'Segundo a Lei 12.288/2010: Políticas Públicas são as ações, iniciativas e programas adotados pelo Estado no cumprimento de suas atribuições institucionais; já Ações Afirmativas são os programas e medidas especiais adotados pelo Estado e pela iniciativa privada para a correção das desigualdades raciais e para a promoção da igualdade de oportunidades.', f: 'Pelo Estatuto da Igualdade Racial, apenas a União pode instituir ações afirmativas, sendo vedada sua adoção pela iniciativa privada.', exp: 'Pegadinha clássica FGV: Políticas Públicas = adotadas pelo ESTADO; Ações Afirmativas = adotadas pelo ESTADO E PELA INICIATIVA PRIVADA!' },
    { sub: 'Direito à Saúde da População Negra e Política Nacional no SUS (Arts. 6º a 8º)', ref: 'Lei 12.288/2010, Arts. 6º a 8º', t: 'O direito à saúde da população negra será garantido pelo poder público mediante políticas universais, sociais e econômicas destinadas à redução do risco de doenças e de outros agravos, sendo a Política Nacional de Saúde Integral da População Negra parte integrante do Sistema Único de Saúde (SUS), incluindo incentivos à pesquisa e tratamento de doenças geneticamente mais prevalentes (como a doença falciforme).', f: 'O Estatuto da Igualdade Racial determina a criação de uma rede hospitalar separada fora do SUS para atender a população negra.', exp: 'As ações de saúde da população negra integram o SUS (Art. 6º, §2º), observando a universalidade e a equidade.' },
    { sub: 'Educação, Cultura, Liberdade de Consciência e Matrizes Africanas (Arts. 11 a 26)', ref: 'Lei 12.288/2010, Arts. 11 a 26', t: 'Nos estabelecimentos de ensino fundamental e de ensino médio, públicos e privados, é obrigatório o estudo da história geral da África e da história da população negra no Brasil; além disso, é assegurado o livre exercício dos cultos religiosos de matriz africana, o reconhecimento da capoeira como bem de natureza imaterial e a assistência religiosa aos praticantes internados em hospitais ou em estabelecimentos prisionais.', f: 'O estudo da história geral da África e da população negra no Brasil é obrigatório apenas nas escolas públicas estaduais de ensino médio.', exp: 'Art. 11 da Lei 12.288/2010 (e Art. 26-A da LDB, alterado pelas Leis 10.639/03 e 11.645/08): é obrigatório no ensino FUNDAMENTAL e MÉDIO, tanto em escolas PÚBLICAS quanto PRIVADAS!' },
    { sub: 'Sistema Nacional de Promoção da Igualdade Racial (SINAPIR) e Ouvidorias Permanentes', ref: 'Lei 12.288/2010, Arts. 47 a 56', t: 'A Lei 12.288/2010 instituiu o Sistema Nacional de Promoção da Igualdade Racial (SINAPIR) como forma de organização e articulação voltadas à implementação do conjunto de políticas e serviços destinados a superar as desigualdades étnicas; os Estados, o DF e os Municípios poderão participar do SINAPIR mediante adesão, e o poder público federal instituirá Ouvidorias Permanentes em Defesa da Igualdade Racial.', f: 'A adesão de Estados e Municípios ao SINAPIR é compulsória sob pena de intervenção federal imediata.', exp: 'Art. 48, §1º da Lei 12.288/2010: os Estados, o DF e os Municípios poderão participar do SINAPIR mediante ADESÃO (voluntária, com incentivo do poder público federal).' }
  ],
  3: [
    { sub: 'Objetivo e Abrangência do Estatuto da Igualdade Racial e de Combate à Intolerância Religiosa da Bahia (Lei Estadual 13.182/2014)', ref: 'Lei Estadual BA 13.182/2014', t: 'A Lei Estadual nº 13.182/2014 instituiu o Estatuto da Igualdade Racial e de Combate à Intolerância Religiosa do Estado da Bahia, destinado a garantir à população negra a efetivação da igualdade de oportunidades, a defesa de direitos individuais, coletivos e difusos e o combate à discriminação e às demais formas de intolerância étnica e religiosa.', f: 'A Lei Estadual nº 13.182/2014 da Bahia trata apenas de incentivos fiscais industriais, omitindo o combate à intolerância religiosa.', exp: 'Diferencial do Estatuto Baiano (Lei 13.182/2014): já no próprio título e estrutura integra a Igualdade Racial com o Combate à Intolerância Religiosa!' },
    { sub: 'Reserva de Vagas em Concursos Públicos e REDA no Estado da Bahia (Art. 49 da Lei 13.182/2014)', ref: 'Lei Estadual BA 13.182/2014, Art. 49', t: 'Nos termos do Art. 49 do Estatuto da Igualdade Racial da Bahia (Lei 13.182/2014), ficam reservados aos negros (pretos e pardos) 30% (trinta por cento) das vagas oferecidas nos concursos públicos para provimento de cargos efetivos e empregos públicos no âmbito da Administração Pública Estadual Direta e Indireta, bem como nos processos seletivos simplificados (REDA), sempre que o número de vagas oferecidas for igual ou superior a 03 (três).', f: 'No Estado da Bahia, o percentual de cotas para candidatos negros em concursos públicos estaduais é de apenas 10% das vagas.', exp: 'Atenção máxima para a prova da SEFAZ-BA! Na esfera Federal a cota era de 20% (Lei 12.990/14, ampliada recentemente para 30%), e no Estado da BAHIA (Art. 49 da Lei 13.182/2014) a reserva para negros é de 30% (TRINTA POR CENTO) quando houver 3 ou mais vagas!' },
    { sub: 'Cômputo de Aprovados na Ampla Concorrência e Desistência no Estatuto Baiano (Art. 49, §§ 3º a 5º)', ref: 'Lei Estadual BA 13.182/2014, Art. 49', t: 'Segundo a Lei Estadual 13.182/2014 da Bahia, os candidatos negros aprovados dentro do número de vagas oferecido para ampla concorrência NÃO serão computados para efeito do preenchimento das vagas reservadas à cota de 30%; em caso de desistência de candidato negro aprovado em vaga reservada, a vaga será preenchida pelo candidato negro posteriormente classificado.', f: 'Na Bahia, o candidato autodeclarado negro que obtiver nota suficiente para passar em 1º lugar geral ocupa obrigatoriamente uma vaga da cota, reduzindo as vagas dos demais cotistas.', exp: 'Se o candidato negro passa pela nota na Ampla Concorrência, ele entra pela Ampla e NÃO consome vaga da cota de 30%! Se não houver candidatos negros aprovados suficientes, as vagas remanescentes revertem para a ampla concorrência.' },
    { sub: 'Reserva de Vagas em Publicidade Institucional do Estado da Bahia (Art. 60 da Lei 13.182/2014)', ref: 'Lei Estadual BA 13.182/2014, Art. 60', t: 'Na produção de peças publicitárias e campanhas institucionais contratadas pelos órgãos e entidades da Administração Pública Estadual da Bahia (com mais de duas pessoas), deverá ser observado o percentual mínimo de 50% (cinquenta por cento) de artistas, modelos e trabalhadores negros.', f: 'A Lei Estadual 13.182/2014 proíbe a participação de artistas negros em campanhas publicitárias estaduais.', exp: 'Art. 60 da Lei Baiana 13.182/2014: mínimo de 50% de participação de pessoas negras nas peças publicitárias governamentais estaduais (refletindo a maioria populacional negra da Bahia).' },
    { sub: 'Rede de Combate ao Racismo e à Intolerância Religiosa e Centro Nelson Mandela na Bahia', ref: 'Lei Estadual BA 13.182/2014', t: 'O Estatuto Baiano prevê a atuação articulada da Rede de Combate ao Racismo e à Intolerância Religiosa e do Centro de Referência de Combate ao Racismo e à Intolerância Religiosa Nelson Mandela (vinculado à SEPROMI), além do Fundo Estadual de Promoção da Igualdade Racial e do Conselho de Desenvolvimento da Comunidade Negra (CDCN).', f: 'Na estrutura do Estado da Bahia, o combate ao racismo é atribuição exclusiva da Secretaria da Fazenda.', exp: 'Na Bahia, a SEPROMI, o CDCN e o Centro de Referência Nelson Mandela formam o núcleo institucional de promoção da igualdade racial.' }
  ],
  4: [
    { sub: 'Equiparação da Injúria Racial ao Crime de Racismo (Lei 14.532/2023 na Lei 7.716/1989, Art. 2º-A)', ref: 'Lei 7.716/1989, Art. 2º-A (Lei 14.532/2023)', t: 'Com a promulgação da Lei nº 14.532/2023 (que positivou o entendimento do STF no HC 154.248), a injúria racial foi transferida para o Art. 2º-A da Lei nº 7.716/1989 ("Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional"), com pena de reclusão de 2 a 5 anos e multa, sendo crime de ação penal pública INCONDICIONADA, INAFIANÇÁVEL e IMPRESCRITÍVEL!', f: 'Atualmente, a injúria racial continua sendo um crime de menor potencial ofensivo, afiançável, prescritível em 8 anos e dependente de queixa-crime privada.', exp: 'Atualização legislativa mais cobrada pela FGV! A Lei 14.532/2023 inseriu a injúria racial no Art. 2º-A da Lei 7.716/89 (pena de reclusão de 2 a 5 anos, aumentada de metade se cometida por 2 ou mais pessoas!). No Art. 140, §3º do Código Penal ficaram apenas a injúria por religião, idade ou deficiência!' },
    { sub: 'Abrangência da Lei 7.716/1989 (Raça, Cor, Etnia, Religião, Procedência Nacional e Homotransfobia - ADO 26)', ref: 'Lei 7.716/1989, Art. 1º e ADO 26 STF', t: 'A Lei nº 7.716/1989 pune os crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional; além disso, o STF (na ADO 26 e no MI 4733) enquadrou a homofobia e a transfobia nos tipos penais da Lei nº 7.716/1989 (e na injúria racial) como espécies de racismo social até que o Congresso edite lei específica.', f: 'A Lei nº 7.716/1989 pune exclusivamente atos de discriminação contra pessoas de cor preta, não abrangendo discriminação por religião ou procedência nacional.', exp: 'Os 5 elementos expressos no Art. 1º da Lei 7.716/89: Raça, Cor, Etnia, Religião ou Procedência Nacional (mais homotransfobia por decisão vinculante do STF).' },
    { sub: 'Racismo Recreativo, Contexto Esportivo/Cultural e Redes Sociais (Art. 20 e Art. 20-A da Lei 7.716/89)', ref: 'Lei 7.716/1989, Arts. 20 e 20-A (Lei 14.532/2023)', t: 'Pelas alterações da Lei 14.532/2023 na Lei 7.716/1989: os crimes previstos na Lei terão as penas aumentadas de 1/3 até a metade quando ocorrerem em contexto ou com intuito de descontração, diversão ou recreação ("racismo recreativo", Art. 20-A); e a prática ou incitação ao preconceito (Art. 20) tem pena de reclusão de 2 a 5 anos quando cometida por intermédio dos meios de comunicação social, de publicação em redes sociais/internet ou no contexto de atividades esportivas, religiosas, artísticas ou culturais (com proibição de frequência a estádios por 3 anos!).', f: 'Se a ofensa racial for proferida em tom de piada ou brincadeira ("intuito de recreação"), o agente fica isento de pena.', exp: 'Atenção para a prova! O chamado "racismo recreativo" (piada/descontração) NÃO exclui o crime: pelo contrário, é causa de AUMENTO DE PENA de 1/3 até a metade (Art. 20-A)!' },
    { sub: 'Efeito da Condenação para Servidor Público e Estabelecimento Privado (Arts. 16 e 18 da Lei 7.716/89)', ref: 'Lei 7.716/1989, Arts. 16 e 18', t: 'Nos crimes da Lei 7.716/1989, constituem efeitos da condenação a perda do cargo ou função pública para o servidor público e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses; contudo, esses efeitos NÃO são automáticos, devendo ser motivadamente declarados na sentença pelo juiz (Art. 16, parágrafo único).', f: 'A condenação de um servidor público por crime da Lei 7.716/1989 acarreta a perda automática do cargo, mesmo que o juiz não mencione esse efeito na sentença.', exp: 'Pegadinha clássica FGV (Art. 16, par. único da Lei 7.716/89): a perda do cargo público e a suspensão do estabelecimento (até 3 meses) NÃO são efeitos automáticos — exigem motivação expressa na sentença!' },
    { sub: 'Acompanhamento Obrigatório por Advogado/Defensor e Apologia ao Nazismo (Art. 20, §1º e Art. 20-C)', ref: 'Lei 7.716/1989, Art. 20, §1º e Art. 20-C', t: 'Constitui crime (Art. 20, §1º, pena de reclusão de 2 a 5 anos) fabricar, comercializar, distribuir ou veicular símbolos, emblemas, ornamentos, distintivos ou propaganda que utilizem a cruz suástica ou gamada, para fins de divulgação do nazismo; além disso, em todos os atos processuais, cíveis e penais, a vítima dos crimes de racismo deverá estar acompanhada de advogado ou defensor público (Art. 20-D), devendo o juiz considerar como discriminatória qualquer atitude que cause constrangimento desproporcional a grupo vulnerabilizado (Art. 20-C).', f: 'A fabricação e comercialização da cruz suástica para divulgação do nazismo é considerada apenas contravenção penal punida com advertência.', exp: 'Divulgação da suástica para fins de nazismo = crime do Art. 20, §1º da Lei 7.716/89 (reclusão de 2 a 5 anos e multa).' }
  ],
  5: [
    { sub: 'Jurisprudência do STF sobre Constitucionalidade das Cotas (ADPF 186 e ADC 41)', ref: 'STF - ADPF 186 (Universidades) e ADC 41 (Concursos)', t: 'O Supremo Tribunal Federal declarou a constitucionalidade integral tanto das cotas étnico-raciais em universidades públicas (ADPF 186, por unanimidade) quanto da reserva de vagas para negros em concursos públicos (ADC 41), firmando a tese de que é legítima a utilização, além da autodeclaração, de critérios subsidiários de heteroidentificação (comissões verificadoras baseadas no fenótipo), desde que respeitados a dignidade da pessoa humana, o contraditório e a ampla defesa.', f: 'Segundo o STF na ADC 41, a administração pública é proibida de instituir comissões de heteroidentificação para confirmar a autodeclaração do candidato.', exp: 'Tese vinculante do STF (ADC 41): a autodeclaração goza de presunção relativa e pode ser verificada por comissão de heteroidentificação baseada em critérios fenotípicos (e não genotípicos/ascendência remota), garantidos o contraditório e a ampla defesa.' },
    { sub: 'Critério Fenotípico vs. Critério Genotípico na Heteroidentificação', ref: 'Heteroidentificação em Concursos', t: 'Nas bancas de heteroidentificação em concursos públicos brasileiros, o critério utilizado para aferir a condição de pessoa negra (preta ou parda) é exclusivamente o FENÓTIPO (conjunto de características físicas visíveis do próprio candidato, como cor da pele, textura do cabelo e traços faciais, que o sujeitam socialmente à discriminação no Brasil, "preconceito de marca"), não sendo aceita a mera ascendência familiar remota (genótipo) se o candidato tiver fenótipo branco.', f: 'Nas comissões de heteroidentificação de concursos públicos, basta apresentar a certidão de nascimento de um bisavô negro para ter a autodeclaração deferida, independentemente das características físicas do candidato.', exp: 'Conforme sociologia de Oracy Nogueira adotada pelo STF e CNJ: no Brasil predomina o "preconceito de marca" (fenótipo/aparência física), e não o "preconceito de origem" (sangue/ascendência).' },
    { sub: 'Lei de Cotas no Ensino Federal (Lei 12.711/2012 e Atualização pela Lei 14.723/2023)', ref: 'Lei 12.711/2012 (atualizada pela Lei 14.723/2023)', t: 'Nas universidades e institutos federais (Lei 12.711/2012, atualizada pela Lei 14.723/2023), 50% das vagas por curso e turno são reservadas a estudantes que cursaram integralmente o ensino médio em escolas públicas (sendo metade para renda familiar per capita $\\le 1$ salário-mínimo), com subcotas proporcionais à população da UF segundo o IBGE para pretos, pardos, indígenas, QUILOMBOLAS e pessoas com deficiência; pela Lei 14.723/2023, o candidato cotista concorre PRIMEIRO na ampla concorrência e, só se não alcançar a nota da ampla, disputa a vaga reservada!', f: 'Com a reforma de 2023 da Lei 12.711/2012, os estudantes quilombolas foram excluídos do sistema de reserva de vagas nas universidades federais.', exp: 'Três grandes novidades da Lei 14.723/2023 na Lei de Cotas do Ensino: (1) inclusão expressa dos QUILOMBOLAS nas subcotas; (2) redução do corte de renda da subcota social de 1,5 para 1 salário-mínimo per capita; e (3) concorrência prioritária na ampla concorrência antes de acionar a cota!' },
    { sub: 'Reserva de Vagas em Concursos Públicos Federais e CNJ (Lei 12.990/2014 e Nova Lei de Cotas)', ref: 'Cotas no Serviço Público', t: 'No âmbito do serviço público, a política de reserva de vagas aplica-se sempre que o número de vagas oferecidas no concurso for igual ou superior a 3 (três); os candidatos negros concorrem concomitantemente às vagas reservadas e às vagas destinadas à ampla concorrência, de acordo com a sua classificação no concurso, e os aprovados dentro do número de vagas da ampla concorrência não são computados para o preenchimento das vagas reservadas.', f: 'O candidato que optar por concorrer às vagas reservadas a pessoas negras fica impedido de ser nomeado pelas vagas de ampla concorrência, mesmo que tire a maior nota da prova.', exp: 'Regra universal (Federal e Estadual da Bahia): o cotista concorre SIMULTANEAMENTE na ampla concorrência e na cota; se sua nota dá para passar na ampla, ele entra pela ampla e libera a vaga da cota para o próximo cotista!' },
    { sub: 'Hipótese de Declaração Falsa e Fraude às Cotas', ref: 'Controle de Fraudes nas Cotas', t: 'Na hipótese de constatação de declaração falsa (fraude comprovada com má-fé), o candidato será eliminado do concurso e, se houver sido nomeado, ficará sujeito à anulação da sua admissão ao serviço ou emprego público, após procedimento administrativo em que lhe sejam assegurados o contraditório e a ampla defesa, sem prejuízo de outras sanções cabíveis.', f: 'Constatada fraude dolosa na autodeclaração após a posse, o servidor adquire estabilidade imediata e não pode ter sua admissão anulada.', exp: 'A anulação da admissão por declaração falsa exige processo administrativo com contraditório e ampla defesa.' }
  ],
  6: [
    { sub: 'Criação e Finalidade da SEPROMI na Bahia (Lei Estadual 10.549/2006)', ref: 'Lei Estadual BA 10.549/2006', t: 'A Lei Estadual nº 10.549/2006 (que modificou a estrutura organizacional da Administração Pública do Poder Executivo do Estado da Bahia) criou a Secretaria de Promoção da Igualdade Racial (SEPROMI, posteriormente denominada Secretaria de Promoção da Igualdade Racial e dos Povos e Comunidades Tradicionais), com a finalidade de planejar e executar políticas de promoção da igualdade racial e de proteção dos direitos de indivíduos e grupos raciais e étnicos, com ênfase na população negra, afetados por discriminação racial e demais formas de intolerância.', f: 'A SEPROMI é uma empresa pública federal vinculada ao Ministério da Economia sem atuação no Estado da Bahia.', exp: 'A SEPROMI foi criada na Bahia pela Lei Estadual nº 10.549/2006 como órgão da Administração Direta do Poder Executivo Estadual!' },
    { sub: 'Conselho de Desenvolvimento da Comunidade Negra (CDCN) e Órgãos Vinculados à SEPROMI', ref: 'Lei Estadual BA 10.549/2006 e 13.182/2014', t: 'Integram a estrutura da Secretaria de Promoção da Igualdade Racial (SEPROMI) no Estado da Bahia órgãos colegiados como o Conselho de Desenvolvimento da Comunidade Negra (CDCN) e o Conselho Estadual para a Sustentabilidade dos Povos e Comunidades Tradicionais (CESPCT), além da Coordenação Executiva de Políticas para a Igualdade Racial e da Coordenação Executiva de Políticas para os Povos e Comunidades Tradicionais.', f: 'O Conselho de Desenvolvimento da Comunidade Negra (CDCN) foi extinto pela Lei Estadual nº 10.549/2006.', exp: 'O CDCN (criado originalmente em 1987 na Bahia) passou a integrar a estrutura da SEPROMI com a Lei Estadual 10.549/2006.' },
    { sub: 'Atribuições da SEPROMI na Articulação Transversal de Políticas Públicas', ref: 'Competências da SEPROMI', t: 'Compete à SEPROMI articular-se com os demais órgãos e entidades estaduais, municipais, federais e organizações da sociedade civil para promover a transversalidade das políticas de igualdade racial, apoiar a regularização fundiária e o desenvolvimento sustentável das comunidades remanescentes de quilombos e povos tradicionais, e combater o racismo institucional e a intolerância religiosa.', f: 'Compete à SEPROMI julgar recursos fiscais de ICMS em substituição ao Conselho de Fazenda Estadual (CONSEF).', exp: 'O papel da SEPROMI é transversal: articula saúde, educação, cultura, trabalho, terra/quilombos e direitos humanos sob o recorte étnico-racial.' },
    { sub: 'Fundo Estadual de Promoção da Igualdade Racial (FEPIR) e Financiamento na Bahia', ref: 'Lei Estadual BA 13.182/2014', t: 'O Estado da Bahia conta com mecanismos orçamentários e fundos específicos, como o Fundo Estadual de Promoção da Igualdade Racial, vinculados à SEPROMI para financiar projetos, ações afirmativas, fortalecimento de comunidades tradicionais, terreiros de matriz africana e enfrentamento ao racismo.', f: 'É vedada a destinação de dotações do orçamento estadual da Bahia para programas de promoção da igualdade racial.', exp: 'Tanto o PPA quanto a LDO e a LOA do Estado da Bahia contemplam programas específicos sob gestão da SEPROMI.' },
    { sub: 'Década Internacional de Afrodescendentes e Programas Estaduais da Bahia', ref: 'Políticas Estaduais da Bahia', t: 'O Estado da Bahia aderiu pioneiramente à Década Internacional de Afrodescendentes da ONU (reconhecimento, justiça e desenvolvimento), instituindo políticas estaduais de titulação e assistência a comunidades quilombolas e de fundo de pasto, proteção ao patrimônio imaterial das religiões de matriz africana e cotas de 30% no serviço público estadual.', f: 'A legislação baiana proíbe o reconhecimento de comunidades tradicionais de fundo e fecho de pasto.', exp: 'Na Bahia, além dos quilombolas e indígenas, têm proteção legal e constitucional expressa as comunidades tradicionais de Fundo e Fecho de Pasto, marisqueiras, extrativistas e povos de terreiro.' }
  ],
  7: [
    { sub: 'Direito Constitucional à Propriedade Definitiva das Terras Quilombolas (Art. 68 do ADCT da CF/88)', ref: 'CF/88, ADCT, Art. 68', t: 'Nos termos do Art. 68 do Ato das Disposições Constitucionais Transitórias (ADCT) da CF/88, aos remanescentes das comunidades dos quilombos que estejam ocupando suas terras é reconhecida a PROPRIEDADE DEFINITIVA, devendo o Estado emitir-lhes os respectivos títulos.', f: 'O Art. 68 do ADCT concede às comunidades quilombolas apenas uma permissão precária e temporária de uso por cinco anos, revogável a qualquer tempo.', exp: 'Diferença crucial de prova (CF/88): para os Povos Indígenas (Art. 231 da CF/88), as terras são bens da UNIÃO e os indígenas têm a posse permanente e o usufruto exclusivo; já para os QUILOMBOLAS (Art. 68 do ADCT), é reconhecida a PROPRIEDADE DEFINITIVA coletiva!' },
    { sub: 'Natureza do Título de Propriedade Quilombola (Coletivo, Pró-Indiviso, Inalienável, Impenhorável e Imprescritível)', ref: 'Decreto 4.887/2003, Art. 17', t: 'Segundo o Decreto nº 4.887/2003 (declarado constitucional pelo STF na ADI 3239), a titulação das terras quilombolas é reconhecida e registrada mediante outorga de título COLETIVO e PRÓ-INDIVISO à respectiva associação legalmente constituída da comunidade, com cláusula obrigatória de INALIENABILIDADE, IMPRESCRITIBILIDADE e IMPENHORABILIDADE.', f: 'O título de terra quilombola é emitido individualmente em lotes particulares que podem ser livremente vendidos ou hipotecados a bancos comerciais.', exp: 'Características do título quilombola (Decreto 4.887/03, Art. 17): Coletivo + Pró-indiviso + Inalienável + Imprescritível + Impenhorável!' },
    { sub: 'Critério de Autoatribuição das Comunidades Remanescentes de Quilombos (Decreto 4.887/2003 e Convenção 169 da OIT)', ref: 'Decreto 4.887/2003, Art. 2º', t: 'Consideram-se remanescentes das comunidades dos quilombos os grupos étnico-raciais, segundo critérios de AUTOATRIBUIÇÃO, com trajetória histórica própria, dotados de relações territoriais específicas, com presunção de ancestralidade negra relacionada com a resistência à opressão histórica sofrida, sendo a caracterização atestada mediante autodefinição da própria comunidade (certificada pela Fundação Cultural Palmares), sem exigir prova de "fuga de escravizados em 1888" (STF, ADI 3239).', f: 'Segundo o STF na ADI 3239, só têm direito à titulação as comunidades que comprovarem documentalmente em cartório que o terreno era um quilombo militar exatamente no dia 5 de outubro de 1988.', exp: 'No julgamento histórico da ADI 3239, o STF rejeitou a tese do marco temporal restritivo para quilombolas e validou o critério da AUTOATRIBUIÇÃO da Convenção 169 da OIT e do Decreto 4.887/2003!' },
    { sub: 'Tombamento Constitucional dos Documentos e Sítios de Quilombos (Art. 216, §5º da CF/88)', ref: 'CF/88, Art. 216, §5º', t: 'O Art. 216, §5º da Constituição Federal decreta diretamente o tombamento constitucional de todos os documentos e os sítios detentores de reminiscências históricas dos antigos quilombos.', f: 'A Constituição Federal proíbe o tombamento de sítios históricos de antigos quilombos.', exp: 'Art. 216, §5º da CF/88: "Ficam tombados todos os documentos e os sítios detentores de reminiscências históricas dos antigos quilombos" (único tombamento feito diretamente pelo próprio texto constitucional!).' },
    { sub: 'Política Nacional de Desenvolvimento Sustentável dos Povos e Comunidades Tradicionais (Decreto 6.040/2007)', ref: 'Decreto 6.040/2007', t: 'O Decreto nº 6.040/2007 define Povos e Comunidades Tradicionais como grupos culturalmente diferenciados e que se reconhecem como tais, que possuem formas próprias de organização social, que ocupam e usam territórios e recursos naturais como condição para sua reprodução cultural, social, religiosa, ancestral e econômica, utilizando conhecimentos, inovações e práticas gerados e transmitidos pela tradição.', f: 'O Decreto nº 6.040/2007 restringe o conceito de comunidades tradicionais exclusivamente aos povos indígenas isolados da Amazônia.', exp: 'Povos e Comunidades Tradicionais abrangem quilombolas, indígenas, povos de terreiro, ciganos, ribeirinhos, pescadores artesanais/marisqueiras, quebradeiras de coco babaçu, comunidades de fundo de pasto, geraizeiros, caiçaras, etc.' }
  ],
  8: [
    { sub: 'Convenção nº 169 da OIT sobre Povos Indígenas e Tribais: Consulta Prévia, Livre e Informada', ref: 'Convenção 169 da OIT (Decreto 10.088/2019)', t: 'A Convenção nº 169 da Organização Internacional do Trabalho (OIT) consagra a consciência da própria identidade (autoidentificação) como critério fundamental para determinar os grupos aos quais se aplica e obriga os governos a realizar CONSULTA PRÉVIA, LIVRE E INFORMADA, de boa-fé e por meio de procedimentos apropriados, aos povos interessados (indígenas, quilombolas e comunidades tradicionais) sempre que sejam previstas medidas legislativas ou administrativas suscetíveis de afetá-los diretamente.', f: 'A Convenção nº 169 da OIT autoriza a remoção forçada de comunidades tradicionais sem qualquer consulta prévia ou indenização.', exp: 'Os dois pilares mais cobrados da Convenção 169 da OIT: (1) Autoidentificação como critério fundamental; e (2) Direito à Consulta Prévia, Livre e Informada antes de obras, mineração ou atos legislativos/administrativos que os afetem diretamente!' },
    { sub: 'Convenção nº 111 da OIT (Discriminação em Matéria de Emprego e Profissão)', ref: 'Convenção 111 da OIT', t: 'A Convenção nº 111 da OIT proíbe qualquer distinção, exclusão ou preferência fundada em raça, cor, sexo, religião, opinião política, ascendência nacional ou origem social que tenha por efeito destruir ou alterar a igualdade de oportunidades ou de tratamento em matéria de emprego ou profissão; ressalva, porém, que as distinções baseadas nas qualificações exigidas para um determinado emprego e as medidas especiais de proteção/assistência não são consideradas discriminação.', f: 'A Convenção nº 111 da OIT proíbe que um edital de concurso público exija diploma de nível superior para o cargo de Auditor Fiscal.', exp: 'Exigências técnicas inerentes à natureza da atividade profissional (qualificação para o cargo) e ações afirmativas não configuram discriminação ilícita na Convenção 111 da OIT.' },
    { sub: 'Declaração e Programa de Ação de Durban (III Conferência Mundial contra o Racismo, 2001)', ref: 'Conferência de Durban (2001)', t: 'A III Conferência Mundial contra o Racismo, Discriminação Racial, Xenofobia e Intolerância Correlata (realizada pela ONU em Durban, África do Sul, em 2001) foi o marco histórico internacional que impulsionou a adoção de ações afirmativas e cotas raciais no Brasil, reconhecendo que a escravidão e o tráfico transatlântico de escravizados constituíram crimes contra a humanidade e que os Estados devem adotar políticas reparatórias para afrodescendentes e povos indígenas.', f: 'Na Conferência de Durban de 2001, a delegação brasileira votou contra a criação de ações afirmativas e defendeu a tese da democracia racial plena.', exp: 'Durban (2001) foi o divisor de águas que levou o Brasil a criar políticas de cotas nas universidades (a partir de 2001/2002 na UERJ e UNEB), a Lei 10.639/2003 e o Estatuto da Igualdade Racial.' },
    { sub: 'Pacto Internacional dos Direitos Civis e Políticos (PIDCP) vs. Pacto dos Direitos Econômicos, Sociais e Culturais (PIDESC)', ref: 'Pactos da ONU de 1966', t: 'Na Carta Internacional dos Direitos Humanos da ONU (Declaração Universal de 1948 + Pactos de 1966): o PIDCP consagra direitos civis e políticos de aplicação IMEDIATA (vedando a propaganda em favor da guerra e qualquer apologia do ódio nacional, racial ou religioso que constitua incitamento à discriminação - Art. 20); já o PIDESC consagra direitos econômicos, sociais e culturais de aplicação PROGRESSIVA até o máximo dos recursos disponíveis, mas a obrigação de NÃO DISCRIMINAR no exercício desses direitos tem aplicação IMEDIATA!', f: 'Segundo o Pacto Internacional dos Direitos Econômicos, Sociais e Culturais (PIDESC), os Estados podem praticar discriminação salarial racial por vinte anos sob a alegação de falta de recursos financeiros.', exp: 'Pegadinha clássica de Direitos Humanos: embora os direitos sociais do PIDESC tenham realização progressiva, a cláusula de NÃO DISCRIMINAÇÃO por raça, cor ou sexo tem aplicação IMEDIATA!' },
    { sub: 'Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica, 1969)', ref: 'Pacto de São José da Costa Rica (Decreto 678/1992)', t: 'A Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica) proíbe a escravidão e a servidão em todas as suas formas (Art. 6º, direito inderrogável inclusive em estado de guerra ou emergência), veda a propaganda a favor da guerra e qualquer apologia ao ódio nacional, racial ou religioso que constitua incitação à violência (Art. 13, §5º), e conta com dois órgãos de supervisão: a Comissão Interamericana de Direitos Humanos (CIDH) e a Corte Interamericana de Direitos Humanos.', f: 'Qualquer cidadão brasileiro pode ajuizar uma ação diretamente perante a Corte Interamericana de Direitos Humanos sem passar antes pela Comissão Interamericana.', exp: 'No Sistema Interamericano: o indivíduo peticiona à COMISSÃO Interamericana (CIDH); apenas a Comissão e os Estados-partes têm legitimidade para submeter um caso à CORTE Interamericana (jurisdição contenciosa reconhecida pelo Brasil em 1998 para fatos posteriores a dezembro de 1998)!' }
  ],
  9: [
    { sub: 'Síntese FGV: Quadro Constitucional e Tratados com Status de Emenda (Art. 5º, §3º)', ref: 'Revisão Geral Igualdade Racial FGV', t: 'Na CF/88: o racismo (e a injúria racial, Art. 2º-A da Lei 7.716/89) é crime inafiançável, imprescritível e sujeito a pena de reclusão (Art. 5º, XLII); aos quilombolas é reconhecida a propriedade definitiva (Art. 68 do ADCT) e seus documentos/sítios históricos são tombados (Art. 216, §5º); e a Convenção Interamericana contra o Racismo (Decreto 10.932/2022) possui status de EMENDA CONSTITUCIONAL (Art. 5º, §3º).', f: 'A Convenção da ONU sobre a Eliminação da Discriminação Racial de 1965 (CERD) tem status inferior às leis ordinárias federais.', exp: 'CERD (1965) e CEDAW (1979) = status SUPRALEGAL; Convenção Interamericana contra o Racismo (promulgada em 2022) = status de EMENDA CONSTITUCIONAL!' },
    { sub: 'Síntese FGV: Estatuto Nacional (Lei 12.288/2010) vs. Estatuto da Bahia (Lei 13.182/2014)', ref: 'Revisão Geral Igualdade Racial FGV', t: 'Na Lei 12.288/2010: População Negra = soma de pretos e pardos (IBGE); Políticas Públicas são adotadas pelo Estado, enquanto Ações Afirmativas são adotadas pelo Estado E pela iniciativa privada; a adesão de Estados/Municípios ao SINAPIR é voluntária. Na Lei Estadual da Bahia nº 13.182/2014: reservam-se 30% das vagas em concursos públicos e REDA para negros (quando houver $\\ge 3$ vagas) e mínimo de 50% de participação negra em peças publicitárias estaduais.', f: 'No Estatuto da Igualdade Racial da Bahia (Lei 13.182/2014), a reserva de vagas em concursos estaduais só se aplica quando o edital oferece mais de 50 vagas.', exp: 'Tanto na lei federal quanto no Estatuto Baiano (Art. 49 da Lei 13.182/2014, cota de 30%), a reserva aplica-se sempre que o número de vagas oferecidas for igual ou superior a 03 (TRÊS)!' },
    { sub: 'Síntese FGV: Lei 7.716/1989 com as Alterações da Lei 14.532/2023', ref: 'Revisão Geral Igualdade Racial FGV', t: 'Na Lei 7.716/1989 (atualizada pela Lei 14.532/2023): (1) a injúria racial está no Art. 2º-A (reclusão de 2 a 5 anos, aumentada de metade se cometida por 2 ou mais pessoas, ação pública incondicionada, inafiançável e imprescritível); (2) o racismo recreativo (intuito de descontração/diversão) aumenta a pena de 1/3 até a metade (Art. 20-A); (3) a perda do cargo público não é efeito automático da condenação, exigindo motivação na sentença (Art. 16, par. único); e (4) a vítima deve estar acompanhada de advogado ou defensor público em todos os atos processuais (Art. 20-D).', f: 'Com a Lei 14.532/2023, a injúria por motivo de religião ou deficiência foi transferida para a Lei 7.716/1989.', exp: 'Cuidado extremo na FGV: para o Art. 2º-A da Lei 7.716/89 foram apenas Raça, Cor, Etnia ou Procedência Nacional! Já a injúria referente a RELIGIÃO ou à condição de pessoa IDOSA ou com DEFICIÊNCIA permaneceu no Art. 140, §3º do Código Penal (reclusão de 1 a 3 anos)!' },
    { sub: 'Síntese FGV: Cotas em Universidades (Lei 12.711/12 + Lei 14.723/23) e Jurisprudência do STF', ref: 'Revisão Geral Igualdade Racial FGV', t: 'Pela jurisprudência do STF (ADPF 186 e ADC 41), são constitucionais as cotas e as comissões de heteroidentificação baseadas no fenótipo (preconceito de marca, garantido o contraditório); na Lei 12.711/2012 (atualizada pela Lei 14.723/2023), os estudantes quilombolas foram incluídos nas subcotas, o corte de renda caiu para 1 salário-mínimo per capita e o cotista concorre primeiro na ampla concorrência.', f: 'Segundo o STF, a heteroidentificação em concursos públicos deve ser feita por exame laboratorial de DNA.', exp: 'A aferição de heteroidentificação analisa exclusivamente características fenotípicas visíveis (jamais exame de DNA ou árvore genealógica).' },
    { sub: 'Síntese FGV: Quilombolas (Decreto 4.887/2003, ADI 3239) e Convenção 169 da OIT', ref: 'Revisão Geral Igualdade Racial FGV', t: 'Para as comunidades remanescentes de quilombos (Art. 68 do ADCT e Decreto 4.887/2003, validado na ADI 3239) e povos tradicionais (Convenção 169 da OIT), prevalece o critério da autoatribuição/autoidentificação, o direito à consulta prévia, livre e informada sobre medidas que os afetem diretamente, e a outorga de título coletivo, pró-indiviso, inalienável, imprescritível e impenhorável.', f: 'As terras quilombolas tituladas podem ser penhoradas para pagamento de dívidas tributárias estaduais.', exp: 'O título coletivo quilombola possui cláusula legal obrigatória de inalienabilidade, imprescritibilidade e impenhorabilidade (Art. 17 do Decreto 4.887/2003).' }
  ]
};
